/** All translations for zizhitongjian ch.013 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起閼逢攝提格，盡昭陽大淵獻，凡十年。", literal: "From Quefeng Shotige through Zhaoyang Dayuanxian; ten years in all.", idiomatic: "From Quefeng Shotige through Zhaoyang Dayuanxian—ten years in all." },
  { zh: "1冬，太后議欲立諸呂為王，問右丞相陵。", literal: "1. In winter the Empress Dowager deliberated on enfeoffing the various Lü as kings and questioned the right chancellor, Ling.", idiomatic: "1. In winter the Empress Dowager resolved to enfeoff the Lü clan as kings and asked the right chancellor, Wang Ling." },
  { zh: "陵曰：「高帝刑白馬盟曰：『非劉氏而王，天下共擊之。", literal: "Ling said: \"When the High Emperor slew the white horse for the oath he declared: 'Whoever is made king though not of the Liu clan—all under Heaven shall strike him together.", idiomatic: "Ling said, \"When the High Emperor slew the white horse for the oath, he declared: 'Whoever is made king though not of the Liu clan—all under Heaven shall strike him down together." },
  { zh: "』今王呂氏，非約也。", literal: "' Now to make the Lü clan kings is against the covenant.\"", idiomatic: "' To make the Lü clan kings now is to break that covenant.\"" },
  { zh: "」太后不說，問左丞相平、太尉勃，對曰：「高帝定天下，王子弟；", literal: "\" The Empress Dowager was displeased and questioned the left chancellor Ping and the Grand Commandant Bo; they answered: \"The High Emperor settled all under Heaven and made his sons and younger brothers kings;", idiomatic: "\" The Empress Dowager was displeased and turned to the left chancellor Chen Ping and the Grand Commandant Zhou Bo. They answered, \"The High Emperor settled the realm and made his sons and brothers kings;" },
  { zh: "今太后稱制，王諸呂，無所不可。", literal: "now the Empress Dowager holds the regency—making the various Lü kings, nothing is impossible.\"", idiomatic: "now Your Majesty holds the regency—if you wish to make the Lü kings, what cannot be done?\"" },
  { zh: "」太后喜，罷朝。", literal: "\" The Empress Dowager was pleased and dismissed court.", idiomatic: "\" The Empress Dowager was pleased and dismissed court." },
  { zh: "王陵讓陳平、絳侯曰：「始與高帝啑血盟，諸君不在邪？", literal: "Wang Ling reproached Chen Ping and the Marquis of Jiang, saying: \"At the outset we joined the High Emperor in the blood oath—were you gentlemen not there?", idiomatic: "Wang Ling reproached Chen Ping and the Marquis of Jiang: \"At the outset we joined the High Emperor in the blood oath—were you not there?" },
  { zh: "今高帝崩，太后女主，欲王呂氏；", literal: "Now the High Emperor is dead, the Empress Dowager is mistress of the realm, and wishes to make the Lü kings;", idiomatic: "Now the High Emperor is dead, the Empress Dowager rules as sovereign, and wishes to make the Lü kings;" },
  { zh: "諸君縱欲阿意背約，何面目見高帝於地下乎？", literal: "if you gentlemen would only fawn and turn your backs on the covenant, with what face can you meet the High Emperor beneath the earth?\"", idiomatic: "if you would only fawn and betray the covenant, with what face will you meet the High Emperor beneath the earth?\"" },
  { zh: "」陳平、降侯曰：「於今，面折廷爭，臣不如君；", literal: "\" Chen Ping and the Marquis of Jiang said: \"For today, to refute to the face and contend in court, your servant is not your equal;", idiomatic: "\" Chen Ping and the Marquis of Jiang said, \"As for refuting to the face and contending in open court, I am not your equal;" },
  { zh: "全社稷，定劉氏之後，君亦不如臣。", literal: "to preserve the altars of state and secure the succession of the Liu clan, you are also not your servant's equal.\"", idiomatic: "but to preserve the altars of state and secure the house of Liu, you are not my equal.\"" },
  { zh: "」陵無以應之。", literal: "\" Ling had nothing with which to reply.", idiomatic: "\" Ling had nothing to say in reply." },
  { zh: "十一月，甲子，太后以王陵為帝太傅，實奪之相權。", literal: "In the eleventh month, on jiazi, the Empress Dowager made Wang Ling Grand Tutor to the Emperor, in truth stripping him of the chancellor's power.", idiomatic: "In the eleventh month, on jiazi, the Empress Dowager made Wang Ling Grand Tutor to the Emperor—in truth stripping him of the chancellor's authority." },
  { zh: "陵遂病免歸。", literal: "Ling then pleaded illness, resigned, and returned home.", idiomatic: "Ling then pleaded illness, resigned, and went home." },
  { zh: "乃以左丞相平為右丞相，以辟陽侯審食其為左丞相，不治事，令監宮中，如郎中令。", literal: "Thereupon the left chancellor Ping was made right chancellor, and the Marquis of Piyang Shen Yishi was made left chancellor; he did not govern affairs but was ordered to oversee the inner palace, like the superintendent of the imperial clan.", idiomatic: "Thereupon Chen Ping was moved from left to right chancellor, and the Marquis of Piyang Shen Yishi was made left chancellor; he did not govern affairs but was ordered to oversee the inner palace, like the superintendent of the imperial clan." },
  { zh: "食其故得幸於太后，公卿皆因而決事。", literal: "Yishi had long enjoyed favor with the Empress Dowager, and the highest ministers all relied on him to decide affairs.", idiomatic: "Yishi had long enjoyed the Empress Dowager's favor, and the highest ministers all decided affairs through him." },
  { zh: "太后怨趙堯為趙隱王謀，乃抵堯罪。", literal: "The Empress Dowager resented Zhao Yao for plotting on behalf of the Hidden King of Zhao and therefore charged Yao with a crime.", idiomatic: "The Empress Dowager resented Zhao Yao for plotting on behalf of the Hidden King of Zhao and therefore charged him with a crime." },
  { zh: "上黨守任敖嘗為沛獄吏，有德於太后，乃以為御史大夫。", literal: "Ren Ao, governor of Shangdang, had once been a jail clerk in Pei and had shown kindness to the Empress Dowager; he was therefore made grand secretary.", idiomatic: "Ren Ao, governor of Shangdang, had once been a jail clerk in Pei and had done the Empress Dowager a kindness; he was therefore made grand secretary." },
  { zh: "太后又追尊其父臨泗侯呂公為宣王，兄周呂令武侯澤為悼武王，欲以王諸呂為漸。", literal: "The Empress Dowager further posthumously honored her father, Marquis of Linsi Duke Lü, as King Xuan, and her elder brother Marquis Wu of Zhoulü Lingwu Ze as King Dao, intending to make kings of the various Lü by degrees.", idiomatic: "The Empress Dowager further posthumously honored her father, Marquis of Linsi Duke Lü, as King Xuan, and her elder brother Marquis Wu of Zhoulü Lingwu Ze as King Dao—laying the groundwork to make the Lü kings by degrees." },
  { zh: "----2春，正月，除三族罪、妖言令。", literal: "----2 In spring, the first month, the crime of exterminating three clans and the ban on perverse speech were abolished.", idiomatic: "----2 In spring, the first month, the crime of exterminating three clans and the ban on perverse speech were abolished." },
  { zh: "----3夏，四月，魯元公主薨。", literal: "----3 In summer, the fourth month, Princess Yuan of Lu died.", idiomatic: "----3 In summer, the fourth month, Princess Yuan of Lu died." },
  { zh: "封公主子張偃為魯王，謚公主曰魯元太后。", literal: "Her son Zhang Yan was enfeoffed as king of Lu, and the princess was given the posthumous title Empress Dowager Yuan of Lu.", idiomatic: "Her son Zhang Yan was enfeoffed as king of Lu, and the princess was given the posthumous title Empress Dowager Yuan of Lu." },
  { zh: "----4辛卯，封所名孝惠子山為襄城侯，朝為軹侯，武為壺關侯。", literal: "----4 On xinmao, the sons named as sons of Emperor Hui—Shan was enfeoffed as Marquis of Xiangcheng, Chao as Marquis of Zhi, Wu as Marquis of Huguan.", idiomatic: "----4 On xinmao, those styled as sons of Emperor Hui—Shan as Marquis of Xiangcheng, Chao as Marquis of Zhi, Wu as Marquis of Huguan—were enfeoffed." },
  { zh: "太后欲王呂氏，乃先立所名孝惠子強為淮陽王，不疑為恆山王；", literal: "The Empress Dowager wished to make the Lü kings; she therefore first installed those named as sons of Emperor Hui—Qiang as king of Huaiyang, Buyi as king of Hengshan;", idiomatic: "The Empress Dowager wished to make the Lü kings; she therefore first installed those styled as sons of Emperor Hui—Qiang as king of Huaiyang, Buyi as king of Hengshan;" },
  { zh: "使大謁者張釋風大臣。", literal: "she had the grand usher Zhang Shi stir up the great ministers.", idiomatic: "she had the grand usher Zhang Shi stir the great ministers." },
  { zh: "大臣乃請立悼武王長子酈侯台為呂王，割齊之濟南郡為呂國。", literal: "The great ministers then requested that the eldest son of King Dao, Marquis Li Tai, be installed as king of Lü, and the prefecture of Jinan in Qi was cut off to form the state of Lü.", idiomatic: "The great ministers then requested that the eldest son of King Dao, Marquis Li Tai, be installed as king of Lü, and Jinan prefecture in Qi was carved off to form the state of Lü." },
  { zh: "----5五月，丙申，趙王宮叢台災。", literal: "----5 In the fifth month, on bingshen, the Cluster Terrace of the Zhao king's palace caught fire.", idiomatic: "----5 In the fifth month, on bingshen, the Cluster Terrace of the Zhao king's palace caught fire." },
  { zh: "----6秋，桃、李華。", literal: "----6 In autumn, peach and plum trees flowered.", idiomatic: "----6 In autumn, peach and plum trees flowered out of season." },
  { zh: "----1冬，十一月，呂肅王台薨。", literal: "----1 In winter, the eleventh month, King Su of Lü, Tai, died.", idiomatic: "----1 In winter, the eleventh month, King Su of Lü, Tai, died." },
  { zh: "----2春，正月，乙卯，地震；", literal: "----2 In spring, the first month, on yimao, there was an earthquake;", idiomatic: "----2 In spring, the first month, on yimao, there was an earthquake;" },
  { zh: "羌道、武都道山崩。", literal: "mountains collapsed on the roads at Qiangdao and Wudu.", idiomatic: "mountains collapsed on the roads at Qiangdao and Wudu." },
  { zh: "----3夏，五月，丙申，封楚元王子郢客為上邳侯，齊悼惠王子章為朱虛侯，令入宿衛，又以呂祿女妻章。", literal: "----3 In summer, the fifth month, on bingshen, the son of King Yuan of Chu, Ying Ke, was enfeoffed as Marquis of Shangpi, and the son of King Huaihui of Qi, Zhang, as Marquis of Zhuwei; both were ordered to join the palace guard, and Lü Lu's daughter was also given to Zhang in marriage.", idiomatic: "----3 In summer, the fifth month, on bingshen, Ying Ke, son of King Yuan of Chu, was enfeoffed as Marquis of Shangpi, and Zhang, son of King Huaihui of Qi, as Marquis of Zhuwei; both were ordered into the palace guard, and Lü Lu's daughter was given to Zhang in marriage." },
  { zh: "----4六月，丙戌晦，日有食之。", literal: "----4 In the sixth month, on the last day bingxu, there was an eclipse of the sun.", idiomatic: "----4 In the sixth month, on the last day bingxu, there was a solar eclipse." },
  { zh: "----5秋，七月，恆山哀王不疑薨。", literal: "----5 In autumn, the seventh month, King Ai of Hengshan, Buyi, died.", idiomatic: "----5 In autumn, the seventh month, King Ai of Hengshan, Buyi, died." },
  { zh: "----6行八銖錢。", literal: "----6 Eight-zhu coins were put in circulation.", idiomatic: "----6 Eight-zhu coins were put in circulation." },
  { zh: "----7癸丑，立襄成侯山為恆山王，更名義。", literal: "----7 On guichou, Marquis of Xiangcheng Shan was installed as king of Hengshan and renamed Yi.", idiomatic: "----7 On guichou, Marquis of Xiangcheng Shan was installed as king of Hengshan and renamed Yi." },
  { zh: "----1夏，江水、漢水溢，流四千餘家。", literal: "----1 In summer, the Yangtze and Han rivers overflowed, drowning more than four thousand households.", idiomatic: "----1 In summer, the Yangtze and Han overflowed, drowning more than four thousand households." },
  { zh: "----2秋，星晝見。", literal: "----2 In autumn, stars were seen in daytime.", idiomatic: "----2 In autumn, stars were seen in daytime." },
  { zh: "----3伊水、洛水溢，流千六百餘家。", literal: "----3 The Yi and Luo rivers overflowed, drowning more than sixteen hundred households.", idiomatic: "----3 The Yi and Luo overflowed, drowning more than sixteen hundred households." },
  { zh: "汝水溢，流八百餘家。", literal: "The Ru River overflowed, drowning more than eight hundred households.", idiomatic: "The Ru overflowed, drowning more than eight hundred households." },
  { zh: "----1春，二月，癸未，立所名孝惠子太為昌平侯。", literal: "----1 In spring, the second month, on guiwei, the son named as Emperor Hui's, Tai, was installed as Marquis of Changping.", idiomatic: "----1 In spring, the second month, on guiwei, the son styled as Emperor Hui's, Tai, was installed as Marquis of Changping." },
  { zh: "----2夏，四月，丙申，太后封女弟嬃為臨光侯。", literal: "----2 In summer, the fourth month, on bingshen, the Empress Dowager enfeoffed her younger sister by a different mother, Xu, as Marquis of Linguang.", idiomatic: "----2 In summer, the fourth month, on bingshen, the Empress Dowager enfeoffed her younger half-sister Xu as Marquis of Linguang." },
  { zh: "----3少帝浸長，自知非皇后子，乃出言曰：「-{后}-安能殺吾母而名我？", literal: "----3 The young Emperor was gradually growing up; knowing he was not the empress's son, he spoke out: \"-{后}—how could she kill my mother and call me hers?", idiomatic: "----3 The young Emperor was gradually growing up; knowing he was not the empress's son, he spoke out: \"-{后}—how could she kill my mother and call me her son?" },
  { zh: "我壯，即為變！", literal: "When I am grown, there will be a reckoning!\"", idiomatic: "When I am grown, there will be a reckoning!\"" },
  { zh: "」太后聞之，幽之永巷中，言帝病，左右莫得見。", literal: "\" When the Empress Dowager heard it, she confined him in the Eternal Lane, announced that the Emperor was ill, and none of his attendants might see him.", idiomatic: "\" When the Empress Dowager heard it, she confined him in the Eternal Lane, announced that the Emperor was ill, and none of his attendants might see him." },
  { zh: "太后語群臣曰：「今皇帝病久不已，失惑昏亂，不能繼嗣治天下；", literal: "The Empress Dowager told the ministers: \"The Emperor has long been ill without recovery; he is muddled and deranged and cannot succeed to rule all under Heaven;", idiomatic: "The Empress Dowager told the ministers, \"The Emperor has long been ill without recovery; he is muddled and deranged and cannot succeed to rule the realm;" },
  { zh: "其代之。", literal: "let him be replaced.\"", idiomatic: "let him be replaced.\"" },
  { zh: "」群臣皆頓首言：「皇太后為天下齊民計，所以安宗廟、社稷甚深。", literal: "\" The ministers all bowed their heads and said: \"The Empress Dowager has reckoned for the common people of all under Heaven; how deep her means to secure the imperial temples and altars of state.", idiomatic: "\" The ministers all bowed their heads and said, \"The Empress Dowager has reckoned for the common people; how deep her care for the imperial temples and altars of state." },
  { zh: "群臣頓首奉詔。", literal: "The ministers bowed their heads and accepted the decree.", idiomatic: "The ministers bowed their heads and accepted the decree." },
  { zh: "」遂廢帝，幽殺之。", literal: "\" Thereupon they deposed the Emperor and secretly killed him.", idiomatic: "\" Thereupon they deposed the Emperor and killed him in secret." },
  { zh: "五月，丙辰，立恆山王義為帝，更名曰弘，不稱元年，以太后制天下事故也。", literal: "In the fifth month, on bingchen, King Yi of Hengshan was installed as Emperor, renamed Hong; the first year was not proclaimed, because the Empress Dowager governed all under Heaven.", idiomatic: "In the fifth month, on bingchen, King Yi of Hengshan was installed as Emperor and renamed Hong; the first year was not proclaimed, because the Empress Dowager governed the realm." },
  { zh: "以軹侯朝為恆山王。", literal: "Marquis of Zhi Chao was made king of Hengshan.", idiomatic: "Marquis of Zhi Chao was made king of Hengshan." },
  { zh: "----4是歲，以平陽侯曹窋為御史大夫。", literal: "----4 This year Marquis of Pingyang Cao Chu was made grand secretary.", idiomatic: "----4 This year Marquis of Pingyang Cao Chu was made grand secretary." },
  { zh: "----5有司請禁南越關市、鐵器。", literal: "----5 The responsible offices requested a ban on market trade and ironware with Nanyue.", idiomatic: "----5 The responsible offices requested a ban on frontier markets and ironware with Nanyue." },
  { zh: "南越王佗曰：「高帝立我，通使物。", literal: "The king of Nanyue, Tuo, said: \"The High Emperor installed me and allowed the exchange of envoys and goods.", idiomatic: "The king of Nanyue, Tuo, said, \"The High Emperor installed me and allowed the exchange of envoys and goods." },
  { zh: "今高后聽讒臣，別異蠻夷，隔絕器物，此必長沙王計，欲倚中國擊滅南越而並王之，自為功也。", literal: "Now the High Empress listens to slanderous ministers, treats the barbarians as separate, and cuts off vessels and tools—this must be the plan of the king of Changsha, who wishes to rely on the central lands to strike down and destroy Nanyue and annex it as king himself, making it his own achievement.\"", idiomatic: "Now the High Empress listens to slanderous ministers, treats the barbarians as alien, and cuts off goods and iron—this must be the king of Changsha's design, to rely on the central court to destroy Nanyue and annex it himself, making that his achievement.\"" },
  { zh: "1春，佗自稱南越武帝，發兵攻長沙，敗數縣而去。", literal: "1. In spring Tuo styled himself Emperor Wu of Nanyue, sent troops to attack Changsha, defeated several counties, and withdrew.", idiomatic: "1. In spring Tuo styled himself Emperor Wu of Nanyue, sent troops against Changsha, defeated several counties, and withdrew." },
  { zh: "----2秋，八月，淮陽懷王強薨，以壺關侯武為淮陽王。", literal: "----2 In autumn, the eighth month, King Huai of Huaiyang, Qiang, died; Marquis of Huguan Wu was made king of Huaiyang.", idiomatic: "----2 In autumn, the eighth month, King Huai of Huaiyang, Qiang, died; Marquis of Huguan Wu was made king of Huaiyang." },
  { zh: "----3九月，發河東、上黨騎屯北地。", literal: "----3 In the ninth month, cavalry from Hedong and Shangdang were mobilized to garrison Beidi.", idiomatic: "----3 In the ninth month, cavalry from Hedong and Shangdang were mobilized to garrison Beidi." },
  { zh: "----4初令戍卒歲更。", literal: "----4 For the first time border garrisons were ordered to rotate yearly.", idiomatic: "----4 For the first time border garrisons were ordered to rotate yearly." },
  { zh: "----1冬，十月，太后以呂王嘉居處驕恣，廢之。", literal: "----1 In winter, the tenth month, the Empress Dowager deposed King Jia of Lü for arrogant and unrestrained conduct in his dwelling.", idiomatic: "----1 In winter, the tenth month, the Empress Dowager deposed King Jia of Lü for arrogant and unrestrained conduct." },
  { zh: "十一月，立肅王弟產為呂王。", literal: "In the eleventh month, the younger brother of King Su, Chan, was installed as king of Lü.", idiomatic: "In the eleventh month, the younger brother of King Su, Chan, was installed as king of Lü." },
  { zh: "----2春，星晝見。", literal: "----2 In spring, stars were seen in daytime.", idiomatic: "----2 In spring, stars were seen in daytime." },
  { zh: "----3夏，四月，丁酉，赦天下。", literal: "----3 In summer, the fourth month, on dingyou, all under Heaven was pardoned.", idiomatic: "----3 In summer, the fourth month, on dingyou, all under Heaven was pardoned." },
  { zh: "----4封朱虛侯章弟興居為東牟侯，亦入宿衛。", literal: "----4 Zhang's younger brother Xingju was enfeoffed as Marquis of Dongmou and also joined the palace guard.", idiomatic: "----4 Zhang's younger brother Xingju was enfeoffed as Marquis of Dongmou and also joined the palace guard." },
  { zh: "----5匈奴寇狄道，攻阿陽。", literal: "----5 The Xiongnu raided Didao and attacked Ayang.", idiomatic: "----5 The Xiongnu raided Didao and attacked Ayang." },
  { zh: "----6行五分錢。", literal: "----6 Five-fen coins were put in circulation.", idiomatic: "----6 Five-fen coins were put in circulation." },
  { zh: "----7宣平侯張敖卒，賜謚曰魯元王。", literal: "----7 Marquis of Xuanping Zhang Ao died and was given the posthumous title King Yuan of Lu.", idiomatic: "----7 Marquis of Xuanping Zhang Ao died and was given the posthumous title King Yuan of Lu." },
  { zh: "----1冬，十二月，匈奴寇狄道，略二千餘人。", literal: "----1 In winter, the twelfth month, the Xiongnu raided Didao and carried off more than two thousand people.", idiomatic: "----1 In winter, the twelfth month, the Xiongnu raided Didao and carried off more than two thousand people." },
  { zh: "----2春，正月，太后召趙幽王友。", literal: "----2 In spring, the first month, the Empress Dowager summoned King You of Zhao, the Secluded King.", idiomatic: "----2 In spring, the first month, the Empress Dowager summoned King You of Zhao, the Secluded King." },
  { zh: "友以諸呂女為-{后}-，弗愛，愛他姬。", literal: "You had taken a daughter of the Lü clan as -{后}- but did not love her; he loved another consort.", idiomatic: "You had taken a daughter of the Lü clan as -{后}- but did not love her; he loved another consort." },
  { zh: "諸呂女怒，去，讒之於太后曰：「王言『呂氏安得王？", literal: "The Lü daughter was enraged, left, and slandered him to the Empress Dowager, saying: \"The king said, 'How can the Lü clan be made kings?", idiomatic: "The Lü daughter was enraged, left, and slandered him to the Empress Dowager, saying, \"The king said, 'How can the Lü clan be made kings?" },
  { zh: "太后百歲後，吾必擊之。", literal: "After the Empress Dowager passes her hundred years, I will surely strike them.'\"", idiomatic: "After the Empress Dowager passes her hundred years, I will surely strike them.'\"" },
  { zh: "』」太后以故召趙王，趙王至，置邸，不得見，令衛圍守之，弗與食；", literal: "'\" For this reason the Empress Dowager summoned the king of Zhao; when the king of Zhao arrived, he was lodged at the guesthouse but could not be received; she ordered guards to surround and hold him and would not give him food;", idiomatic: "'\" For this reason the Empress Dowager summoned the king of Zhao; when he arrived, he was lodged at the guesthouse but could not be received; she ordered guards to surround him and would not give him food;" },
  { zh: "其群臣或竊饋，輒捕論之。", literal: "if any of his ministers secretly fed him, they were immediately seized and prosecuted.", idiomatic: "if any of his ministers secretly fed him, they were immediately seized and prosecuted." },
  { zh: "丁丑，趙王餓死，以民禮葬之長安民塚次。", literal: "On dingchou, the king of Zhao starved to death; he was buried with commoners' rites in the commoners' burial ground at Chang'an.", idiomatic: "On dingchou, the king of Zhao starved to death; he was buried with commoners' rites in the commoners' burial ground at Chang'an." },
  { zh: "----3己丑，日食，晝晦。", literal: "----3 On jichou, there was an eclipse; daytime grew dark.", idiomatic: "----3 On jichou, there was an eclipse; daytime grew dark." },
  { zh: "太后惡之，謂左右曰：「此為我也！", literal: "The Empress Dowager hated it and said to those beside her: \"This is on account of me!", idiomatic: "The Empress Dowager took it ill and said to those beside her, \"This is aimed at me!" },
  { zh: "」----4二月，徙梁王恢為趙王，呂王產為梁王。", literal: "\" ----4 In the second month, King Hui of Liang was moved to be king of Zhao, and King Chan of Lü was made king of Liang.", idiomatic: "\" ----4 In the second month, King Hui of Liang was moved to Zhao, and King Chan of Lü was made king of Liang." },
  { zh: "梁王不之國，為帝太傅。", literal: "The king of Liang did not go to his state but became Grand Tutor to the Emperor.", idiomatic: "The king of Liang did not go to his state but became Grand Tutor to the Emperor." },
  { zh: "----5秋，七月，丁巳，立平昌侯太為濟川王。", literal: "----5 In autumn, the seventh month, on dingsi, Marquis of Pingchang Tai was installed as king of Jichuan.", idiomatic: "----5 In autumn, the seventh month, on dingsi, Marquis of Pingchang Tai was installed as king of Jichuan." },
  { zh: "----6呂嬃女為將軍、營陵侯劉澤妻。", literal: "----6 Lü Xu had a daughter who was wife to the general and Marquis of Yingling, Liu Ze.", idiomatic: "----6 Lü Xu's daughter was wife to the general and Marquis of Yingling, Liu Ze." },
  { zh: "澤者，高祖從祖昆弟也。", literal: "Ze was a cousin in the collateral line of the High Ancestor.", idiomatic: "Ze was a cousin of the High Ancestor on the collateral line." },
  { zh: "齊人田生為之說大謁者張卿曰：「諸呂之王也，諸大臣未大服。", literal: "The man of Qi, Tian Sheng, spoke on his behalf to the grand usher Zhang Qing, saying: \"When the various Lü were made kings, the great ministers were not greatly persuaded.", idiomatic: "The man of Qi, Tian Sheng, spoke on his behalf to the grand usher Zhang Qing: \"When the Lü were made kings, the great ministers were not fully persuaded." },
  { zh: "今營陵侯澤，諸劉最長；", literal: "Now Marquis of Yingling Ze is the eldest among the various Liu;", idiomatic: "Now Marquis of Yingling Ze is the eldest among the Liu;" },
  { zh: "今卿言太后王之，呂氏王益固矣。", literal: "if you, sir, speak to the Empress Dowager to make him king, the kingship of the Lü clan would be all the firmer.\"", idiomatic: "if you speak to the Empress Dowager to make him king, the Lü kingship would be all the firmer.\"" },
  { zh: "」張卿入言太后，太后然之，乃割齊之琅邪郡封澤為琅邪王。", literal: "\" Zhang Qing entered and spoke to the Empress Dowager; she approved, and therefore cut off the prefecture of Langye in Qi and enfeoffed Ze as king of Langye.", idiomatic: "\" Zhang Qing went in and spoke to the Empress Dowager; she approved, cut Langye prefecture from Qi, and enfeoffed Ze as king of Langye." },
  { zh: "----7趙王恢之徙趙，心懷不樂。", literal: "----7 King Hui of Zhao, having been moved to Zhao, harbored discontent in his heart.", idiomatic: "----7 King Hui of Zhao, having been moved to Zhao, was discontent at heart." },
  { zh: "太后以呂產女為王后，王后從官皆諸呂，擅權，微伺趙王，趙王不得自恣。", literal: "The Empress Dowager made Lü Chan's daughter his queen; the queen's attendants were all of the Lü clan; they monopolized power, watched the king of Zhao covertly, and the king of Zhao could not act as he wished.", idiomatic: "The Empress Dowager made Lü Chan's daughter his queen; the queen's attendants were all Lü kin; they monopolized power, watched the king of Zhao covertly, and he could not act as he wished." },
  { zh: "王有所愛姬，王后使人鴆殺之。", literal: "The king had a consort he loved; the queen sent someone to poison her to death.", idiomatic: "The king had a consort he loved; the queen sent someone to poison her." },
  { zh: "六月，王不勝悲憤，自殺。", literal: "In the sixth month, unable to bear grief and rage, the king killed himself.", idiomatic: "In the sixth month, unable to bear grief and rage, the king killed himself." },
  { zh: "太后聞之，以為王用婦人棄宗廟禮，廢其嗣。", literal: "When the Empress Dowager heard it, she held that the king had abandoned the rites of the ancestral temple for a woman's sake and abolished his succession.", idiomatic: "When the Empress Dowager heard it, she held that the king had abandoned the rites of the ancestral temple for a woman's sake and abolished his succession." },
  { zh: "----8是時，諸呂擅權用事。", literal: "----8 At this time the various Lü monopolized power and handled affairs.", idiomatic: "----8 At this time the Lü clan monopolized power and handled affairs." },
  { zh: "朱虛侯章，年二十，有氣力，忿劉氏不得職。", literal: "Marquis of Zhuwei Zhang, twenty years old, had strength and spirit and resented that the Liu clan held no office.", idiomatic: "Marquis of Zhuwei Zhang, twenty years old, was strong and spirited and resented that the Liu clan held no office." },
  { zh: "嘗入侍太后燕飲，太后令章為酒吏。", literal: "Once, entering to attend the Empress Dowager at a banquet, the Empress Dowager ordered Zhang to be wine steward.", idiomatic: "Once, attending the Empress Dowager at a banquet, she ordered Zhang to be wine steward." },
  { zh: "章自請曰：「臣將種也，請得以軍法行酒。", literal: "Zhang requested on his own: \"Your servant is of a general's stock; I beg to enforce the wine according to military law.", idiomatic: "Zhang requested on his own, \"Your servant is of a general's stock; I beg to enforce the wine by military law." },
  { zh: "」太后曰：「可。", literal: "\" The Empress Dowager said: \"It may be done.", idiomatic: "\" The Empress Dowager said, \"It may be done." },
  { zh: "」酒酣，章請為《耕田歌》，太后許之。", literal: "\" When the wine was deep, Zhang requested to perform the \"Ploughing Fields Song\"; the Empress Dowager granted it.", idiomatic: "\" When the wine was deep, Zhang requested to perform the \"Ploughing Fields Song\"; the Empress Dowager granted it." },
  { zh: "章曰：「深耕穊種，立苗欲疏；", literal: "Zhang said: \"Plough deep and sow thick; set the seedlings, wanting them sparse;", idiomatic: "Zhang said, \"Plough deep and sow thick; set the seedlings, wanting them sparse;" },
  { zh: "非其種者，鋤而去之！", literal: "What is not our kind—hoe it up and cast it out!", idiomatic: "What is not our kind—hoe it up and cast it out!" },
  { zh: "」太后默然。", literal: "\" The Empress Dowager was silent.", idiomatic: "\" The Empress Dowager fell silent." },
  { zh: "頃之，諸呂有一人醉，亡酒，章追，拔劍斬之而還，報曰：「有亡酒一人，臣謹行法斬之！", literal: "Shortly after, one of the Lü clan was drunk and fled the wine service; Zhang pursued him, drew his sword and killed him, then returned and reported: \"One man fled the wine service; your servant has duly executed him by military law!", idiomatic: "Shortly after, one of the Lü clan, drunk, fled the wine service; Zhang pursued him, drew his sword and killed him, then reported: \"One man deserted the wine service; your servant has duly executed him by military law!\"" },
  { zh: "」太后左右皆大驚，業已許其軍法，無以罪也，因罷。", literal: "\" Those around the Empress Dowager were all greatly alarmed; she had already approved his military law and could not punish him, and therefore the affair ended.", idiomatic: "\" Those around the Empress Dowager were greatly alarmed; she had already approved his military law and could not punish him, so the banquet ended." },
  { zh: "自是之後，諸呂憚朱虛侯，雖大臣皆依朱虛侯，劉氏為益強。", literal: "From this time on the Lü clan feared the Marquis of Zhu Xu; even the great ministers all relied on the Marquis of Zhu Xu, and the Liu house grew stronger.", idiomatic: "From then on the Lü clan feared the Marquis of Zhu Xu; even the great ministers relied on him, and the Liu house grew stronger." },
  { zh: "陳平患諸呂，力不能制，恐禍及己。", literal: "Chen Ping was troubled by the Lü clan; his strength could not control them, and he feared disaster would reach him.", idiomatic: "Chen Ping was troubled by the Lü clan; he lacked the power to control them and feared disaster would reach him." },
  { zh: "嘗燕居深念，陸賈往，直入坐，而陳丞相不見。", literal: "Once when at ease in private he was deep in thought, Lu Jia came; he went straight in and sat down, yet Chancellor Chen did not receive him.", idiomatic: "Once when at ease in private he was deep in thought, Lu Jia came, went straight in and sat down, yet Chancellor Chen did not receive him." },
  { zh: "陸生曰：「何念之深也！", literal: "Master Lu said: \"How deep your brooding!", idiomatic: "Master Lu said, \"How deep your brooding!\"" },
  { zh: "」陳平曰：「生揣我何念？", literal: "\" Chen Ping said: \"Master, what do you suppose I am brooding on?", idiomatic: "\" Chen Ping said, \"Master, what do you suppose I am brooding on?\"" },
  { zh: "」陸生曰：「足下極富貴，無欲矣；", literal: "\" Master Lu said: \"Your Excellency is supremely rich and noble—you have no further wants;", idiomatic: "\" Master Lu said, \"Your Excellency is supremely rich and noble—you want for nothing;" },
  { zh: "然有憂念，不過患諸呂、少主耳。", literal: "yet you have a worry, and it is nothing beyond fear of the Lü clan and the young sovereign.", idiomatic: "yet you brood on nothing beyond the Lü clan and the young sovereign." },
  { zh: "」陳平曰：「然！", literal: "\" Chen Ping said: \"It is so!", idiomatic: "\" Chen Ping said, \"It is so!\"" },
  { zh: "為之奈何？", literal: "What is to be done about it?", idiomatic: "What is to be done about it?" },
  { zh: "」陸生曰：「天下安，注意相；", literal: "\" Master Lu said: \"When all under Heaven is secure, attend to the chancellor;", idiomatic: "\" Master Lu said, \"When the realm is secure, attend to the chancellor;" },
  { zh: "天下危，注意將。", literal: "when all under Heaven is in peril, attend to the general.", idiomatic: "when the realm is in peril, attend to the general." },
  { zh: "將相和調，則士豫附；", literal: "When general and chancellor are in harmony, then officers gladly attach themselves;", idiomatic: "When general and chancellor are in harmony, officers gladly attach themselves;" },
  { zh: "天下雖有變，權不分。", literal: "though all under Heaven has trouble, power is not divided.", idiomatic: "though trouble comes, power is not divided." },
  { zh: "為社稷計，在兩君掌握耳。", literal: "For the altars of soil and grain, it lies in the grasp of you two lords alone.", idiomatic: "For the realm's sake, it lies in the grasp of you two lords alone." },
  { zh: "臣常欲謂太尉絳侯，絳侯與我戲，易吾言。", literal: "Your servant has often wished to speak to Grand Commandant the Marquis of Jiang, but the Marquis of Jiang jokes with me and makes light of my words.", idiomatic: "I have often wished to speak to Grand Commandant the Marquis of Jiang, but he jokes with me and makes light of my words." },
  { zh: "君何不交歡太尉，深相結？", literal: "Why do you not make friends with the Grand Commandant and bind yourselves deeply?", idiomatic: "Why not make friends with the Grand Commandant and bind yourselves deeply?" },
  { zh: "」因為陳平畫呂氏數事。", literal: "\" He then laid out for Chen Ping several matters concerning the Lü clan.", idiomatic: "\" He then laid out for Chen Ping several matters concerning the Lü clan." },
  { zh: "陳平用其計，乃以五百金為絳侯壽，厚具樂飲；", literal: "Chen Ping used his plan and therefore sent five hundred in gold as a birthday gift to the Marquis of Jiang, lavishly providing music and drink;", idiomatic: "Chen Ping used his plan and sent five hundred in gold as a birthday gift to the Marquis of Jiang, lavishly providing music and drink;" },
  { zh: "太尉報亦如之。", literal: "the Grand Commandant returned the courtesy in like measure.", idiomatic: "and the Grand Commandant returned the courtesy in like measure." },
  { zh: "兩人深相結，呂氏謀益衰。", literal: "The two men bound themselves deeply, and the Lü clan's plots grew ever weaker.", idiomatic: "The two men bound themselves deeply, and the Lü clan's plots grew weaker." },
  { zh: "陳平以奴婢百人、車馬五十乘、錢五百萬遺陸生為飲食費。", literal: "Chen Ping gave Master Lu a hundred slave men and women, fifty teams of chariots and horses, and five million in cash as funds for food and drink.", idiomatic: "Chen Ping gave Master Lu a hundred slaves, fifty teams of chariots and horses, and five million in cash for food and drink." },
  { zh: "----9太后使使告代王，欲徙王趙。", literal: "----9 The Empress Dowager sent envoys to tell the king of Dai that she wished to move his fief to Zhao.", idiomatic: "----9 The Empress Dowager sent envoys to tell the king of Dai that she wished to move his fief to Zhao." },
  { zh: "代王謝之，願守代邊。", literal: "The king of Dai declined and wished to remain guarding the Dai frontier.", idiomatic: "The king of Dai declined and wished to remain guarding the Dai frontier." },
  { zh: "太后乃立兄子呂祿為趙王，追尊祿父建成康侯釋之為趙昭王。", literal: "The Empress Dowager thereupon installed her elder brother's son Lü Lu as king of Zhao and posthumously honored Lu's father, Marquis Kang of Jiancheng Shi Zhi, as King Zhao of Zhao.", idiomatic: "The Empress Dowager thereupon installed her elder brother's son Lü Lu as king of Zhao and posthumously honored Lu's father, Marquis Kang of Jiancheng Shi Zhi, as King Zhao of Zhao." },
  { zh: "----10九月，燕靈王建薨，有美人子，太后使人殺之。", literal: "----10 In the ninth month King Ling of Yan Jian died; he had a son by a beautiful woman, and the Empress Dowager sent men to kill him.", idiomatic: "----10 In the ninth month King Ling of Yan Jian died; he had a son by a concubine, and the Empress Dowager sent men to kill him." },
  { zh: "國除。", literal: "The state was abolished.", idiomatic: "The state was abolished." },
  { zh: "----11遣隆慮侯周灶將兵擊南越。", literal: "----11 The Marquis of Longlu Zhou Zao was sent to lead troops against the Southern Yue.", idiomatic: "----11 The Marquis of Longlu Zhou Zao was sent to lead troops against the Southern Yue." },
  { zh: "----1冬，十月，辛丑，立呂肅王子東平侯通為燕王，封通弟莊為東平侯。", literal: "----1 In winter, the tenth month, on xinchou, the son of King Su of Lü, Marquis of Dongping Tong, was installed as king of Yan, and Tong's younger brother Zhuang was enfeoffed as Marquis of Dongping.", idiomatic: "----1 In winter, the tenth month, on xinchou, the son of King Su of Lü, Marquis of Dongping Tong, was installed as king of Yan, and Tong's younger brother Zhuang was enfeoffed as Marquis of Dongping." },
  { zh: "----2三月，太后祓，還，過軹道，見物如蒼犬，撠太后掖，忽不復見。", literal: "----2 In the third month the Empress Dowager performed the lustration rite; on her return, passing Zhi Road, she saw something like a gray dog that struck her under the arm, then suddenly was seen no more.", idiomatic: "----2 In the third month the Empress Dowager performed the lustration rite; on her return, passing Zhi Road, she saw something like a gray dog that struck her under the arm, then vanished." },
  { zh: "卜之，云「趙王如意為祟」。", literal: "She divined about it; the answer said: \"King Ruyi of Zhao is the haunting spirit.\"", idiomatic: "She divined; the answer said, \"King Ruyi of Zhao is the haunting spirit.\"" },
  { zh: "太后遂病掖傷。", literal: "The Empress Dowager then fell ill from the wound to her arm.", idiomatic: "The Empress Dowager then fell ill from the wound to her arm." },
  { zh: "太后為外孫魯王偃年少孤弱，夏，四月，丁酉，封張敖前姬兩子侈為新都侯，壽為樂昌侯，以輔魯王。", literal: "The Empress Dowager, because her grandson the king of Lu Yan was young, orphaned, and weak, in summer, the fourth month, on dingyou, enfeoffed Zhang Ao's two sons by a former concubine—Zhang Chi as Marquis of Xindu and Zhang Shou as Marquis of Lechang—to assist the king of Lu.", idiomatic: "Because her grandson the king of Lu Yan was young, orphaned, and weak, in summer, the fourth month, on dingyou, she enfeoffed Zhang Ao's two sons by a former concubine—Zhang Chi as Marquis of Xindu and Zhang Shou as Marquis of Lechang—to assist the king of Lu." },
  { zh: "又封中大謁者張釋為建陵侯，以其勸王諸呂，賞之也。", literal: "She also enfeoffed the grand usher Zhang Shi as Marquis of Jianling, rewarding him for having urged the king to support the Lü clan.", idiomatic: "She also enfeoffed the grand usher Zhang Shi as Marquis of Jianling, rewarding him for having urged the king to support the Lü clan." },
  { zh: "----3江、漢水溢，流萬餘家。", literal: "----3 The Yangzi and Han rivers overflowed, drowning more than ten thousand households.", idiomatic: "----3 The Yangzi and Han rivers overflowed, drowning more than ten thousand households." },
  { zh: "----4秋，七月，太后病甚，乃令趙王祿為上將軍，居北軍；", literal: "----4 In autumn, the seventh month, the Empress Dowager was gravely ill and therefore appointed King Zhao Lu as supreme general and stationed him in the Northern Army;", idiomatic: "----4 In autumn, the seventh month, the Empress Dowager was gravely ill and appointed King Zhao Lu as supreme general in the Northern Army;" },
  { zh: "呂王產居南軍。", literal: "King Lü Chan was stationed in the Southern Army.", idiomatic: "King Lü Chan was stationed in the Southern Army." },
  { zh: "太后誡產、祿曰：「呂氏之王，大臣弗平。", literal: "The Empress Dowager admonished Chan and Lu, saying: \"The kingship of the Lü clan—the great ministers are not reconciled.", idiomatic: "The Empress Dowager admonished Chan and Lu: \"The Lü kingships—the great ministers are not reconciled." },
  { zh: "我即崩，帝年少，大臣恐為變。", literal: "When I soon die, the Emperor is young, and the great ministers may fear trouble.", idiomatic: "When I soon die, the Emperor is young, and the great ministers may fear trouble." },
  { zh: "必據兵衛宮，慎毋送喪，為人所制！", literal: "You must hold troops and guard the palace; take care not to attend the funeral—you will be controlled by others!", idiomatic: "You must hold troops and guard the palace; take care not to attend the funeral—you will be controlled by others!\"" },
  { zh: "」辛巳，太后崩，遺詔：大赦天下，以呂王產為相國，以呂祿女為帝后。", literal: "\" On xinsi the Empress Dowager died; her testamentary edict: a general amnesty for all under Heaven; King Lü Chan to be Chancellor of State; Lü Lu's daughter to be empress.", idiomatic: "\" On xinsi the Empress Dowager died. Her testamentary edict: a general amnesty; King Lü Chan to be Chancellor of State; Lü Lu's daughter to be empress." },
  { zh: "高後已葬，以左丞相審食其為帝太傅。", literal: "After the High Empress Dowager was buried, the left chancellor Shen Yiji was made Imperial Tutor to the Emperor.", idiomatic: "After the High Empress Dowager was buried, the left chancellor Shen Yiji was made Imperial Tutor to the Emperor." },
  { zh: "----5諸呂欲為亂，畏大臣絳、灌等，未敢發。", literal: "----5 The Lü clan wished to make rebellion but feared the great ministers Jiang, Guan, and others, and did not dare act.", idiomatic: "----5 The Lü clan wished to rebel but feared the great ministers Jiang, Guan, and others, and did not dare act." },
  { zh: "朱虛侯以呂祿女為婦，故知其謀，乃陰令人告其兄齊王，欲令發兵西，朱虛侯、東牟侯為內應，以誅諸呂，立齊王為帝。", literal: "The Marquis of Zhu Xu, because he had taken Lü Lu's daughter as wife, therefore knew their plot; he secretly sent men to tell his elder brother the king of Qi, wishing him to raise troops and march west while the Marquis of Zhu Xu and the Marquis of Dongmou served as inner supporters, to execute the Lü clan and install the king of Qi as emperor.", idiomatic: "The Marquis of Zhu Xu, having married Lü Lu's daughter, knew their plot; he secretly sent men to tell his elder brother the king of Qi to raise troops and march west while the Marquis of Zhu Xu and the Marquis of Dongmou served as inner supporters, to execute the Lü clan and install the king of Qi as emperor." },
  { zh: "齊王乃與其舅駟鈞、郎中令祝午、中尉魏勃陰謀發兵。", literal: "The king of Qi then secretly plotted to raise troops with his maternal uncle Si Jun, the director of attendants Zhu Wu, and the commandant of justice Wei Bo.", idiomatic: "The king of Qi then secretly plotted to raise troops with his maternal uncle Si Jun, the director of attendants Zhu Wu, and the commandant of justice Wei Bo." },
  { zh: "齊相召平弗聽。", literal: "The chancellor of Qi, Shao Ping, would not heed him.", idiomatic: "The chancellor of Qi, Shao Ping, would not heed him." },
  { zh: "八月，丙午，齊王欲使人誅相。", literal: "In the eighth month, on bingwu, the king of Qi wished to send men to execute the chancellor.", idiomatic: "In the eighth month, on bingwu, the king of Qi wished to send men to execute the chancellor." },
  { zh: "相聞之，乃發卒衛王宮。", literal: "The chancellor, learning of it, then raised troops to guard the royal palace.", idiomatic: "The chancellor, learning of it, raised troops to guard the royal palace." },
  { zh: "魏勃紿召平曰：「王欲發兵，非有漢虎符驗也。", literal: "Wei Bo deceived Shao Ping, saying: \"The king wishes to raise troops, yet there is no verification by the Han tiger tally.", idiomatic: "Wei Bo deceived Shao Ping: \"The king wishes to raise troops, yet there is no verification by the Han tiger tally." },
  { zh: "而相君圍王固善，勃請為君將兵衛王。", literal: "Yet my lord the chancellor in besieging the king is surely right; Bo asks to lead troops for my lord and guard the king.", idiomatic: "Yet my lord the chancellor in besieging the king is surely right; Bo asks to lead troops for my lord and guard the king.\"" },
  { zh: "」召平信之。", literal: "\" Shao Ping believed him.", idiomatic: "\" Shao Ping believed him." },
  { zh: "勃既將兵，遂圍相府，召平自殺。", literal: "Once Bo had taken command of the troops, he then besieged the chancellor's residence and Shao Ping killed himself.", idiomatic: "Once Bo had taken command, he besieged the chancellor's residence and Shao Ping killed himself." },
  { zh: "於是齊王以駟鈞為相，魏勃為將軍，祝午為內史，悉發國中兵。", literal: "Thereupon the king of Qi made Si Jun chancellor, Wei Bo general, and Zhu Wu director of the interior, and fully mobilized the state's troops.", idiomatic: "Thereupon the king of Qi made Si Jun chancellor, Wei Bo general, and Zhu Wu director of the interior, and fully mobilized the state's troops." },
  { zh: "使祝午東詐琅邪王曰：「呂氏作亂，齊王發兵欲西誅之。", literal: "He sent Zhu Wu east to deceive the king of Langye, saying: \"The Lü clan is in rebellion; the king of Qi has raised troops and wishes to march west to execute them.", idiomatic: "He sent Zhu Wu east to deceive the king of Langye: \"The Lü clan is in rebellion; the king of Qi has raised troops and wishes to march west to execute them." },
  { zh: "齊王自以年少，不習兵革之事，願舉國委大王。", literal: "The king of Qi considers himself young and unskilled in military affairs, and wishes to entrust the whole state to Your Majesty.", idiomatic: "The king of Qi considers himself young and unskilled in military affairs and wishes to entrust the whole state to Your Majesty." },
  { zh: "大王，自高帝將也。", literal: "Your Majesty was yourself a general under High Emperor.", idiomatic: "Your Majesty was yourself a general under the High Emperor." },
  { zh: "請大王幸之臨菑，見齊王計事。", literal: "We beg Your Majesty to favor us with a visit to Linzi to meet the king of Qi and plan affairs.", idiomatic: "We beg Your Majesty to favor us with a visit to Linzi to meet the king of Qi and plan affairs.\"" },
  { zh: "」琅邪王信之，西馳見齊王。", literal: "\" The king of Langye believed it and galloped west to see the king of Qi.", idiomatic: "\" The king of Langye believed it and galloped west to see the king of Qi." },
  { zh: "齊王因留琅邪王，而使祝午盡發琅邪國兵，並將之。", literal: "The king of Qi thereupon detained the king of Langye and sent Zhu Wu to fully mobilize the troops of the state of Langye and take joint command of them.", idiomatic: "The king of Qi detained the king of Langye and sent Zhu Wu to fully mobilize Langye's troops and take joint command." },
  { zh: "琅邪王說齊王曰：「大王，高皇帝適長孫也，當立。", literal: "The king of Langye persuaded the king of Qi, saying: \"Your Majesty, as the eldest grandson by the proper wife of High Emperor, ought to be enthroned.", idiomatic: "The king of Langye persuaded the king of Qi: \"Your Majesty, as the eldest grandson by the proper wife of the High Emperor, ought to be enthroned." },
  { zh: "今諸大臣狐疑未有所定，而澤於劉氏最為長年，大臣固待澤決計。", literal: "Now the great ministers are in doubt and have not settled on anyone, and among the Liu house Ze is the eldest in years; the great ministers surely await Ze to decide the plan.", idiomatic: "Now the great ministers are in doubt and have not settled on anyone; among the Liu house Ze is the eldest in years, and the great ministers surely await Ze to decide." },
  { zh: "今大王留臣，無為也，不如使我入關計事。", literal: "Now if Your Majesty detains your servant, it is of no use; better to let your servant enter the passes and plan affairs.", idiomatic: "If Your Majesty detains me, it is of no use; better to let me enter the passes and plan affairs.\"" },
  { zh: "」齊王以為然，乃益具車送琅邪王。", literal: "\" The king of Qi thought it right and therefore further equipped chariots and sent off the king of Langye.", idiomatic: "\" The king of Qi thought it right and further equipped chariots and sent off the king of Langye." },
  { zh: "琅邪王既行，齊遂舉兵西攻濟南。", literal: "Once the king of Langye had departed, Qi thereupon raised troops and attacked Jinan westward.", idiomatic: "Once the king of Langye had departed, Qi raised troops and attacked Jinan westward." },
  { zh: "遺諸侯王書，陳諸呂之罪，欲舉兵誅之。", literal: "He sent a letter to the feudal kings, setting forth the crimes of the Lü clan and wishing to raise troops to execute them.", idiomatic: "He sent a letter to the feudal kings, setting forth the crimes of the Lü clan and wishing to raise troops to execute them." },
  { zh: "相國呂產等聞之，乃遣穎陰侯灌嬰將兵擊之。", literal: "Chancellor of State Lü Chan and others, hearing of it, then sent the Marquis of Yingyin Guan Ying to lead troops against them.", idiomatic: "Chancellor of State Lü Chan and others, hearing of it, sent the Marquis of Yingyin Guan Ying to lead troops against them." },
  { zh: "灌嬰至滎陽，謀曰：「諸呂擁兵關中，欲危劉氏而自立。", literal: "Guan Ying reached Xingyang and took counsel, saying: \"The Lü clan hold troops in the passes and wish to endanger the Liu house and set themselves up.", idiomatic: "Guan Ying reached Xingyang and took counsel: \"The Lü clan hold troops in the passes and wish to endanger the Liu house and set themselves up." },
  { zh: "今我破齊還報，此益呂氏之資也。", literal: "If I now break Qi and return to report, this only adds to the Lü clan's resources.", idiomatic: "If I now break Qi and return to report, this only adds to the Lü clan's resources.\"" },
  { zh: "」乃留屯滎陽，使使諭齊王及諸侯與連和，以待呂氏變，共誅之。", literal: "\" He therefore remained encamped at Xingyang, sent envoys to instruct the king of Qi and the feudal lords to join in alliance, and waited for trouble from the Lü clan so they might together execute them.", idiomatic: "\" He therefore remained encamped at Xingyang, sent envoys to instruct the king of Qi and the feudal lords to join in alliance, and waited for trouble from the Lü clan so they might together execute them." },
  { zh: "齊王聞之，乃還兵西界待約。", literal: "The king of Qi, hearing of it, then returned his troops to the western border to await the covenant.", idiomatic: "The king of Qi, hearing of it, returned his troops to the western border to await the covenant." },
  { zh: "呂祿、呂產欲作亂，內憚絳侯、朱虛等，外畏齊、楚兵，又恐灌嬰畔之。", literal: "Lü Lu and Lü Chan wished to make rebellion; inwardly they feared the Marquis of Jiang, the Marquis of Zhu Xu, and others; outwardly they feared the troops of Qi and Chu; and they also feared Guan Ying would turn against them.", idiomatic: "Lü Lu and Lü Chan wished to rebel; inwardly they feared the Marquis of Jiang, the Marquis of Zhu Xu, and others; outwardly they feared the troops of Qi and Chu; and they also feared Guan Ying would turn against them." },
  { zh: "欲待灌嬰兵與齊合而發，猶豫未決。", literal: "They wished to wait until Guan Ying's troops joined with Qi's before acting, and hesitated without deciding.", idiomatic: "They wished to wait until Guan Ying's troops joined with Qi's before acting, and hesitated without deciding." },
  { zh: "當是時，濟川王太、淮陽王武、常山王朝及魯王張偃皆年少，未之國，居長安；", literal: "At this time the kings of Jichuan Tai, Huaiyang Wu, Changshan Chao, and Lu Zhang Yan were all young and had not gone to their states, dwelling in Chang'an;", idiomatic: "At this time the kings of Jichuan Tai, Huaiyang Wu, Changshan Chao, and Lu Zhang Yan were all young and had not gone to their states, dwelling in Chang'an;" },
  { zh: "趙王祿、梁王產各將兵居南、北軍。", literal: "King Zhao Lu and King Liang Chan each commanded troops stationed in the Southern and Northern Armies.", idiomatic: "King Zhao Lu and King Liang Chan each commanded troops in the Southern and Northern Armies." },
  { zh: "皆呂氏之人也。", literal: "all were men of the Lü clan.", idiomatic: "all were men of the Lü clan." },
  { zh: "列侯群臣莫自堅其命。", literal: "The ranked marquises and the host of ministers none could be secure in their lives.", idiomatic: "The ranked marquises and ministers none could be secure in their lives." },
  { zh: "太尉絳侯勃不得主兵。", literal: "Grand Commandant the Marquis of Jiang Bo could not command troops.", idiomatic: "Grand Commandant the Marquis of Jiang Bo could not command troops." },
  { zh: "曲周侯酈商老病，其子寄與呂祿善。", literal: "The Marquis of Quzhou Li Shang was old and ill; his son Ji was on good terms with Lü Lu.", idiomatic: "The Marquis of Quzhou Li Shang was old and ill; his son Ji was on good terms with Lü Lu." },
  { zh: "絳侯乃與丞相陳平謀，使人劫酈商，令其子寄往紿說呂祿曰：「高帝與-{呂后}-共定天下，劉氏所立九王，呂氏所立三王，皆大臣之議，事已佈告諸侯，皆以為宜。", literal: "The Marquis of Jiang then plotted with Chancellor Chen Ping, sent men to seize Li Shang, and had his son Ji go to deceive and persuade Lü Lu, saying: \"High Emperor and -{呂后}- together settled all under Heaven; the nine kings the Liu house installed and the three kings the Lü house installed were all by the great ministers' deliberation; the matter has already been proclaimed to the feudal lords, and all think it fitting.", idiomatic: "The Marquis of Jiang then plotted with Chancellor Chen Ping, sent men to seize Li Shang, and had his son Ji go to deceive Lü Lu: \"The High Emperor and -{呂后}- together settled the realm; the nine kings the Liu house installed and the three the Lü house installed were all by the great ministers' deliberation; the matter has been proclaimed to the feudal lords, and all think it fitting." },
  { zh: "今太后崩，帝少，而足下佩趙王印，不急之國守籓，乃為上將，將兵留此，為大臣諸侯所疑。", literal: "Now the Empress Dowager is dead and the Emperor young, yet Your Excellency wears the seal of king of Zhao, does not hurry to your state to guard your fief, but instead serves as supreme general and keeps troops here—you are suspected by the great ministers and feudal lords.", idiomatic: "Now the Empress Dowager is dead and the Emperor young, yet Your Excellency wears the seal of king of Zhao, does not hurry to your state to guard your fief, but serves as supreme general and keeps troops here—you are suspected by the great ministers and feudal lords." },
  { zh: "足下何不歸將印，以兵屬太尉，請梁王歸相國印，與大臣盟而之國。", literal: "Why does Your Excellency not return the general's seal and entrust the troops to the Grand Commandant, ask King Liang to return the Chancellor of State's seal, covenant with the great ministers, and go to your states?", idiomatic: "Why not return the general's seal and entrust the troops to the Grand Commandant, ask King Liang to return the Chancellor of State's seal, covenant with the great ministers, and go to your states?" },
  { zh: "齊兵必罷，大臣得安，足下高枕而王千里，此萬世之利也。", literal: "Qi's troops will surely be dismissed, the great ministers will be secure, and Your Excellency may lay your head on a high pillow and be king of a thousand li—this is a benefit for ten thousand generations.", idiomatic: "Qi's troops will surely be dismissed, the great ministers will be secure, and you may lay your head on a high pillow and be king of a thousand li—this is a benefit for ten thousand generations.\"" },
  { zh: "」呂祿信然其計，欲以兵屬太尉。", literal: "\" Lü Lu believed this plan was so and wished to entrust the troops to the Grand Commandant.", idiomatic: "\" Lü Lu believed this plan and wished to entrust the troops to the Grand Commandant." },
  { zh: "使人報呂產及諸呂老人，或以為便，或曰不便，計猶豫未有所決。", literal: "He sent men to report to Lü Chan and the elders of the Lü clan; some thought it expedient, some said it was not expedient—the plan hesitated without decision.", idiomatic: "He sent men to report to Lü Chan and the elders of the Lü clan; some thought it expedient, some said it was not—the plan hesitated without decision." },
  { zh: "呂祿信酈寄，時與出遊獵，過其姑呂嬃。", literal: "Lü Lu trusted Li Ji and at times went out with him to hunt, passing his aunt Lü Xu.", idiomatic: "Lü Lu trusted Li Ji and at times went out with him to hunt, passing his aunt Lü Xu." },
  { zh: "嬃大怒曰：「若為將而棄軍，呂氏今無處矣！", literal: "Xu raged and said: \"You serve as general yet abandon the army—the Lü clan today has nowhere to stand!", idiomatic: "Xu raged: \"You serve as general yet abandon the army—the Lü clan today has nowhere to stand!\"" },
  { zh: "」乃悉出珠玉、寶器散堂下，曰：「毋為他人守也！", literal: "\" She then brought out all pearls and jade and precious vessels and scattered them in the hall, saying: \"Do not keep them for others!", idiomatic: "\" She then brought out all pearls, jade, and precious vessels and scattered them in the hall: \"Do not keep them for others!\"" },
  { zh: "九月，庚申旦，平陽侯窋行御史大夫事，見相國產計事。", literal: "In the ninth month, at dawn on gengshen, the Marquis of Pingyang Zhu, acting as Grand Secretary, met Chancellor of State Chan to plan affairs.", idiomatic: "In the ninth month, at dawn on gengshen, the Marquis of Pingyang Zhu, acting as Grand Secretary, met Chancellor of State Chan to plan affairs." },
  { zh: "郎中令賈壽使從齊來，因數產曰：「王不早之國，今雖欲行，尚可得邪！", literal: "Director of attendants Jia Shou's envoy came from Qi and therefore reproached Chan, saying: \"Your Majesty did not go early to your state; though you now wish to go, can you still get away!", idiomatic: "Director of attendants Jia Shou's envoy came from Qi and reproached Chan: \"Your Majesty did not go early to your state; though you now wish to go, can you still get away!\"" },
  { zh: "」具以灌嬰與齊、楚合從欲誅諸呂告產，且趣產急入宮。", literal: "\" He fully told Chan that Guan Ying had joined in horizontal alliance with Qi and Chu and wished to execute the Lü clan, and urged Chan to hurry into the palace.", idiomatic: "\" He fully told Chan that Guan Ying had allied with Qi and Chu and wished to execute the Lü clan, and urged Chan to hurry into the palace." },
  { zh: "平陽侯頗聞其語，馳告丞相、太尉。", literal: "The Marquis of Pingyang had partly overheard these words and galloped to tell the chancellor and Grand Commandant.", idiomatic: "The Marquis of Pingyang had partly overheard these words and galloped to tell the chancellor and Grand Commandant." },
  { zh: "太尉欲入北軍，不得入。", literal: "The Grand Commandant wished to enter the Northern Army but could not enter.", idiomatic: "The Grand Commandant wished to enter the Northern Army but could not enter." },
  { zh: "襄平侯紀通尚符節，乃令持節矯內太尉北軍。", literal: "The Marquis of Xiangping Ji Tong held the tally and credentials; he was therefore ordered to hold the credentials and falsely announce the Grand Commandant's entry into the Northern Army.", idiomatic: "The Marquis of Xiangping Ji Tong held the tally and credentials; he was ordered to hold the credentials and falsely announce the Grand Commandant's entry into the Northern Army." },
  { zh: "太尉復令酈寄與典客劉揭先說呂祿曰：「帝使太尉守北軍，欲足下之國。", literal: "The Grand Commandant again ordered Li Ji and the director of guests Liu Jie first to persuade Lü Lu, saying: \"The Emperor has sent the Grand Commandant to hold the Northern Army and wishes Your Excellency to go to your state.", idiomatic: "The Grand Commandant again ordered Li Ji and the director of guests Liu Jie first to persuade Lü Lu: \"The Emperor has sent the Grand Commandant to hold the Northern Army and wishes you to go to your state." },
  { zh: "急歸將印辭去。", literal: "Hurry back and return the general's seal and resign.", idiomatic: "Hurry back and return the general's seal and resign." },
  { zh: "不然，禍且起。", literal: "If not, disaster will soon arise.", idiomatic: "If not, disaster will soon arise.\"" },
  { zh: "」呂祿以為酈況不欺己，遂解印屬典客，而以兵授太尉。", literal: "\" Lü Lu thought Li Ji would not deceive him, thereupon removed the seal and entrusted it to the director of guests, and gave the troops to the Grand Commandant.", idiomatic: "\" Lü Lu thought Li Ji would not deceive him, removed the seal and entrusted it to the director of guests, and gave the troops to the Grand Commandant." },
  { zh: "太尉至軍，呂祿已去。", literal: "The Grand Commandant reached the army; Lü Lu had already left.", idiomatic: "The Grand Commandant reached the army; Lü Lu had already left." },
  { zh: "太尉入軍門，行令軍中曰：「為呂氏右袒，為劉氏左袒！", literal: "The Grand Commandant entered the camp gate and issued orders in the army, saying: \"Those for the house of Lü, bare the right shoulder; those for the house of Liu, bare the left shoulder!", idiomatic: "The Grand Commandant entered the camp gate and issued orders in the army: \"Those for the house of Lü, bare the right shoulder; those for the house of Liu, bare the left shoulder!\"" },
  { zh: "」軍中皆左袒，太尉遂將北軍。", literal: "\" In the army all bared the left shoulder; the Grand Commandant then took command of the Northern Army.", idiomatic: "\" In the army all bared the left shoulder; the Grand Commandant then took command of the Northern Army." },
  { zh: "然尚有南軍。", literal: "Yet the Southern Army still remained.", idiomatic: "Yet the Southern Army still remained." },
  { zh: "丞相平乃召朱虛侯章佐太尉，太尉令朱虛侯監軍門，令平陽侯告衛尉：「毋入相國產殿門。", literal: "Chancellor Ping then summoned the Marquis of Zhu Xu, Zhang, to assist the Grand Commandant; the Grand Commandant ordered the Marquis of Zhu Xu to supervise the camp gate and ordered the Marquis of Pingyang to tell the Commandant of the Guard: \"Do not let anyone enter Chancellor of State Chan's palace gate.", idiomatic: "Chancellor Ping then summoned the Marquis of Zhu Xu, Zhang, to assist the Grand Commandant; the Grand Commandant ordered the Marquis of Zhu Xu to supervise the camp gate and ordered the Marquis of Pingyang to tell the Commandant of the Guard: \"Do not let anyone enter Chancellor of State Chan's palace gate.\"" },
  { zh: "呂產不知呂祿已去北軍，乃入未央宮，欲為亂。", literal: "Lü Chan did not know Lü Lu had already left the Northern Army; he entered Weiyang Palace, intending to make trouble.", idiomatic: "Lü Chan did not know Lü Lu had already left the Northern Army; he entered Weiyang Palace, intending to make trouble." },
  { zh: "至殿門，弗得入，徘徊往來。", literal: "Reaching the palace gate, he could not enter and paced back and forth.", idiomatic: "Reaching the palace gate, he could not enter and paced back and forth." },
  { zh: "平陽侯恐弗勝，馳語太尉。", literal: "The Marquis of Pingyang feared they would not prevail and galloped to tell the Grand Commandant.", idiomatic: "The Marquis of Pingyang feared they would not prevail and galloped to tell the Grand Commandant." },
  { zh: "太尉尚恐不勝諸呂，未敢公言誅之，乃謂朱虛侯曰：「急入宮衛帝！", literal: "The Grand Commandant still feared he might not overcome the various Lü and did not dare speak openly of executing them; he said to the Marquis of Zhu Xu: \"Hurry into the palace and guard the Emperor!", idiomatic: "The Grand Commandant still feared he might not overcome the various Lü and did not dare speak openly of executing them; he said to the Marquis of Zhu Xu: \"Hurry into the palace and guard the Emperor!\"" },
  { zh: "」朱虛侯請卒，太尉予卒千餘人。", literal: "\" The Marquis of Zhu Xu requested troops; the Grand Commandant gave him more than a thousand men.", idiomatic: "\" The Marquis of Zhu Xu requested troops; the Grand Commandant gave him more than a thousand men." },
  { zh: "入未央宮門，見產廷中。", literal: "Entering Weiyang Palace gate, he saw Chan in the courtyard.", idiomatic: "Entering Weiyang Palace gate, he saw Chan in the courtyard." },
  { zh: "日哺時，遂擊產，產走。", literal: "At the hour of shen he attacked Chan; Chan fled.", idiomatic: "In late afternoon he attacked Chan; Chan fled." },
  { zh: "天風大起，以故其從官亂，莫敢鬬，逐產，殺之郎中府吏廁中。", literal: "A great wind arose; for this reason his followers fell into disorder, none daring to fight; they pursued Chan and killed him in the privy of the Palace Attendant's quarters.", idiomatic: "A great wind arose; his followers fell into disorder and none dared fight; they pursued Chan and killed him in the privy of the Palace Attendant's quarters." },
  { zh: "朱虛侯已殺產，帝命謁者持節勞朱虛侯。", literal: "After the Marquis of Zhu Xu had killed Chan, the Emperor ordered a chamberlain to hold credentials of authority and console the Marquis of Zhu Xu.", idiomatic: "After the Marquis of Zhu Xu had killed Chan, the Emperor ordered a chamberlain to hold credentials of authority and console the Marquis of Zhu Xu." },
  { zh: "朱虛侯欲奪其節，謁者不肯。", literal: "The Marquis of Zhu Xu wished to seize the credentials; the chamberlain would not agree.", idiomatic: "The Marquis of Zhu Xu wished to seize the credentials; the chamberlain would not agree." },
  { zh: "朱虛侯則從與載，因節信馳走，斬長樂衛尉呂更始。", literal: "The Marquis of Zhu Xu then went along with him in the carriage; relying on the credentials' authority he galloped off and beheaded Chang Palace Commandant of the Guard Lü Gengshi.", idiomatic: "The Marquis of Zhu Xu then rode with him in the carriage; relying on the credentials' authority he galloped off and beheaded Chang Palace Commandant of the Guard Lü Gengshi." },
  { zh: "還，馳入北軍報太尉。", literal: "Returning, he galloped into the Northern Army to report to the Grand Commandant.", idiomatic: "Returning, he galloped into the Northern Army to report to the Grand Commandant." },
  { zh: "太尉起，拜賀朱虛侯曰：「所患獨呂產。", literal: "The Grand Commandant rose, bowed in congratulation to the Marquis of Zhu Xu, and said: \"The sole worry was Lü Chan.", idiomatic: "The Grand Commandant rose, bowed in congratulation to the Marquis of Zhu Xu, and said: \"The sole worry was Lü Chan." },
  { zh: "今已誅，天下定矣！", literal: "Now he has been executed—all under Heaven is settled!", idiomatic: "Now he has been executed—the realm is settled!" },
  { zh: "」遂遣人分部悉捕諸呂男女，無少長皆斬之。", literal: "\" Thereupon he sent men in divisions to arrest all the Lü, men and women; none, young or old, was spared execution.", idiomatic: "\" Thereupon he sent men in divisions to arrest all the Lü, men and women; none, young or old, was spared execution." },
  { zh: "辛酉，捕斬呂祿而笞殺呂嬃，使人誅燕王呂通而廢魯王張偃。", literal: "On xinyou, Lü Lu was captured and executed and Lü Xu was flogged to death; envoys were sent to execute King of Yan Lü Tong and depose King of Lu Zhang Yan.", idiomatic: "On xinyou, Lü Lu was captured and executed and Lü Xu was flogged to death; envoys were sent to execute King of Yan Lü Tong and depose King of Lu Zhang Yan." },
  { zh: "戊辰，徙濟川王王梁。", literal: "On wuchen, the King of Jichuan was moved to be King of Liang.", idiomatic: "On wuchen, the King of Jichuan was moved to be King of Liang." },
  { zh: "遣朱虛侯章以誅諸呂事告齊王，令罷兵。", literal: "The Marquis of Zhu Xu, Zhang, was sent to report to the King of Qi about the execution of the Lü and to order him to disband his troops.", idiomatic: "The Marquis of Zhu Xu, Zhang, was sent to report to the King of Qi about the execution of the Lü and to order him to disband his troops." },
  { zh: "灌嬰在滎陽，聞魏勃本教齊王舉兵，使使召魏勃至，責問之。", literal: "Guan Ying was at Xingyang; hearing that Wei Bo had originally urged the King of Qi to raise troops, he sent an envoy to summon Wei Bo; when he arrived, Guan rebuked and questioned him.", idiomatic: "Guan Ying was at Xingyang; hearing that Wei Bo had originally urged the King of Qi to raise troops, he sent an envoy to summon Wei Bo and, when he arrived, rebuked and questioned him." },
  { zh: "勃曰：「失火之家，豈暇先言丈人而後救火乎！", literal: "Bo said: \"In a house where fire has broken out, how could there be leisure to speak first of the father-in-law and only then fight the fire!", idiomatic: "Bo said: \"In a house where fire has broken out, how could there be leisure to speak first of the father-in-law and only then fight the fire!\"" },
  { zh: "」因退立，股戰而栗，恐不能言者，終無他語。", literal: "\" Thereupon he withdrew and stood aside, thighs trembling and shuddering, afraid he could not speak; in the end he said nothing more.", idiomatic: "\" Thereupon he withdrew and stood aside, thighs trembling and shuddering, afraid he could not speak; in the end he said nothing more." },
  { zh: "灌將軍熟視笑曰：「人謂魏勃勇，妄庸人耳，何能為乎！", literal: "General Guan looked at him intently and laughed, saying: \"People call Wei Bo brave—he is a muddled common fellow; what can he do!", idiomatic: "General Guan looked at him intently and laughed: \"People call Wei Bo brave—he is a muddled common fellow; what can he do!\"" },
  { zh: "」乃罷魏勃。", literal: "\" Thereupon he dismissed Wei Bo.", idiomatic: "\" Thereupon he dismissed Wei Bo." },
  { zh: "灌嬰兵亦罷滎陽歸。", literal: "Guan Ying's troops also withdrew from Xingyang and returned.", idiomatic: "Guan Ying's troops also withdrew from Xingyang and returned." },
  { zh: "::班固贊曰：孝文時，天下以酈寄為賣友。", literal: ":: Ban Gu's encomium says: In Emperor Wen's time, all under Heaven took Li Ji as one who sold out his friend.", idiomatic: ":: Ban Gu's encomium says: In Emperor Wen's time, all under Heaven took Li Ji as one who sold out his friend." },
  { zh: "夫賣友者，謂見利而忘義也。", literal: "To sell out a friend means to see profit and forget righteousness.", idiomatic: "To sell out a friend means to see profit and forget righteousness." },
  { zh: "若寄父為功臣而又執劫，雖摧呂祿以安社稷，誼存君親可也。", literal: "If Ji, as the son of a meritorious minister, moreover held him hostage, though he overthrew Lü Lu to secure the altars of soil and grain, it was permissible to preserve lord and kin in righteousness.", idiomatic: "If Ji, as the son of a meritorious minister, moreover held him hostage, though he overthrew Lü Lu to secure the realm, it was permissible to preserve lord and kin in righteousness." },
  { zh: "----6諸大臣相與陰謀曰：「少帝及梁、淮陽、恆山王，皆非真孝惠子也。", literal: "----6 The great ministers together plotted in secret, saying: \"The Young Emperor and the kings of Liang, Huaiyang, and Hengshan are none of them true sons of Emperor Xiaohui.", idiomatic: "----6 The great ministers together plotted in secret: \"The Young Emperor and the kings of Liang, Huaiyang, and Hengshan are none of them true sons of Emperor Xiaohui." },
  { zh: "-{呂后}-以計詐名他人子，殺其母養後宮，令孝惠子之，立以為後及諸王，以強呂氏。", literal: "-{呂后}- by scheme falsely named others' sons, killed their mothers, and raised them in the rear palace, making Emperor Xiaohui's sons of them, establishing one as heir and the various kings, to strengthen the house of Lü.", idiomatic: "-{呂后}- by scheme falsely named others' sons, killed their mothers, and raised them in the rear palace, making them Emperor Xiaohui's sons, establishing one as heir and the various kings, to strengthen the house of Lü." },
  { zh: "今皆已夷滅諸呂，而所立即長，用事，吾屬無類矣。", literal: "Now all the Lü have been exterminated, yet the one enthroned is grown and in power—our sort will have no survivors.", idiomatic: "Now all the Lü have been exterminated, yet the one enthroned is grown and in power—our sort will have no survivors." },
  { zh: "不如視諸王最賢者立之。", literal: "Better to look among the kings for the most worthy and establish him.", idiomatic: "Better to look among the kings for the most worthy and establish him." },
  { zh: "」或言：「齊王，高帝長孫，可立也。", literal: "\" Some said: \"The King of Qi, the High Emperor's eldest grandson, may be established.", idiomatic: "\" Some said: \"The King of Qi, the High Emperor's eldest grandson, may be established." },
  { zh: "」大臣皆曰：「呂氏以外家惡而幾危宗廟，亂功臣。", literal: "\" The great ministers all said: \"The house of Lü, because of evil from the maternal kin, nearly endangered the ancestral temples and threw the merit-holders into disorder.", idiomatic: "\" The great ministers all said: \"The house of Lü, because of evil from the maternal kin, nearly endangered the ancestral temples and threw the merit-holders into disorder." },
  { zh: "今齊王舅駟鈞，虎而冠。", literal: "Now the King of Qi's maternal uncle Siju is a tiger wearing a cap.", idiomatic: "Now the King of Qi's maternal uncle Siju is violent as a tiger wearing a cap." },
  { zh: "即立齊王，復為呂氏矣。", literal: "To establish the King of Qi would be to make the Lü again.", idiomatic: "To establish the King of Qi would be to make the Lü again." },
  { zh: "代王方今高帝見子最長，仁孝寬厚，太后家薄氏謹良。", literal: "The King of Dai is now the longest-lived among the High Emperor's living sons, humane, filial, generous, and lenient; the empress dowager's clan, the house of Bo, is careful and good.", idiomatic: "The King of Dai is now the eldest among the High Emperor's living sons, humane, filial, generous, and lenient; the empress dowager's clan, the house of Bo, is careful and good." },
  { zh: "且立長固順，況以仁孝聞天下乎！", literal: "Moreover to establish the eldest is inherently accordant—how much more when he is known throughout all under Heaven for humanity and filial piety!", idiomatic: "Moreover to establish the eldest is inherently accordant—how much more when he is known throughout the realm for humanity and filial piety!" },
  { zh: "」乃相與共陰使人召代王。", literal: "\" Thereupon together they secretly sent envoys to summon the King of Dai.", idiomatic: "\" Thereupon together they secretly sent envoys to summon the King of Dai." },
  { zh: "代王問左右，郎中令張武等曰：「漢大臣皆故高帝時大將，習兵，多謀詐。", literal: "The King of Dai asked his attendants; Gentlemen-of-the-Palace Zhang Wu and others said: \"The great officers of Han are all former great generals from the High Emperor's time, skilled in war, full of plots and deceit.", idiomatic: "The King of Dai asked his attendants; Gentlemen-of-the-Palace Zhang Wu and others said: \"The great officers of Han are all former great generals from the High Emperor's time, skilled in war, full of plots and deceit." },
  { zh: "此其屬意非止此也，特畏高帝、呂太后威耳。", literal: "Their intent does not stop here; they only fear the authority of the High Emperor and Empress Dowager Lü.", idiomatic: "Their intent does not stop here; they only fear the authority of the High Emperor and Empress Dowager Lü." },
  { zh: "今已誅諸呂，新啑血京師，此以迎大王為名，實不可信。", literal: "Now the Lü have been executed and they have freshly licked blood in the capital—this, though in the name of welcoming Your Majesty, is truly not to be trusted.", idiomatic: "Now the Lü have been executed and they have freshly shed blood in the capital—this, though in the name of welcoming Your Majesty, is truly not to be trusted." },
  { zh: "願大王稱疾毋往，以觀其變。", literal: "I wish that Your Majesty plead illness and not go, to observe how things change.", idiomatic: "I wish that Your Majesty plead illness and not go, to observe how things change." },
  { zh: "」中尉宋昌進曰：「群臣之議皆非也。", literal: "\" Commandant of the Imperial Guards Song Chang advanced and said: \"The counsel of the ministers is all wrong.", idiomatic: "\" Commandant of the Imperial Guards Song Chang advanced and said: \"The counsel of the ministers is all wrong." },
  { zh: "夫秦失其政，諸侯、豪桀並起，人人自以為得之者以萬數，然卒踐天子之位者，劉氏也，天下絕望，一矣。", literal: "When Qin lost its government, feudal lords and powerful heroes rose together; everyone who took himself for the one to obtain it numbered in the tens of thousands—yet in the end the one who trod the Son of Heaven's place was the house of Liu; all under Heaven had given up hope—one thing.", idiomatic: "When Qin lost its government, feudal lords and powerful heroes rose together; everyone who took himself for the one to obtain it numbered in the tens of thousands—yet in the end the one who trod the Son of Heaven's place was the house of Liu; the realm had given up hope—one thing." },
  { zh: "高帝封王子弟，地犬牙相制，此所謂磐石之宗也，天下服其強，二矣。", literal: "The High Emperor enfeoffed sons and younger brothers with territory interlocking like dogs' teeth—this is what is called the clan as bedrock; all under Heaven submitted to its strength—two things.", idiomatic: "The High Emperor enfeoffed sons and younger brothers with territory interlocking like dogs' teeth—this is what is called the clan as bedrock; the realm submitted to its strength—two things." },
  { zh: "漢興，除秦苛政，約法令，施德惠，人人自安，難動搖，三矣。", literal: "Han rose, abolished Qin's harsh government, simplified laws and ordinances, and bestowed virtue and kindness; everyone found security for himself—hard to shake—three things.", idiomatic: "Han rose, abolished Qin's harsh government, simplified laws and ordinances, and bestowed virtue and kindness; everyone found security for himself—hard to shake—three things." },
  { zh: "夫以呂太后之嚴，立諸呂為三王，擅權專制；", literal: "Even under the sternness of Empress Dowager Lü, she established the various Lü as three kings with sole power and authoritarian rule;", idiomatic: "Even under the sternness of Empress Dowager Lü, she established the various Lü as three kings with sole power and authoritarian rule;" },
  { zh: "然而太尉以一節入北軍一呼，士皆左袒為劉氏，叛諸呂，卒以滅之。", literal: "yet the Grand Commandant, with a single credential entering the Northern Army and one shout, every soldier bared the left shoulder for the house of Liu, revolted against the various Lü, and in the end destroyed them.", idiomatic: "yet the Grand Commandant, with a single credential entering the Northern Army and one shout, every soldier bared the left shoulder for the house of Liu, revolted against the various Lü, and in the end destroyed them." },
  { zh: "此乃天授，非人力也。", literal: "This was Heaven's grant—not human strength.", idiomatic: "This was Heaven's grant—not human strength." },
  { zh: "今大臣雖欲為變，百姓弗為使，其黨寧能專一邪？", literal: "Now though the great ministers wished to make trouble, the common people would not serve them; could their faction achieve singleness of purpose?", idiomatic: "Now though the great ministers wished to make trouble, the common people would not serve them; could their faction achieve singleness of purpose?" },
  { zh: "方今內有朱虛、東牟之親，外畏吳、楚、淮陽、琅邪、齊、代之強。", literal: "Now within there are kin such as Zhu Xu and Dong Mou; without, they fear the strength of Wu, Chu, Huaiyang, Langye, Qi, and Dai.", idiomatic: "Now within there are kin such as Zhu Xu and Dong Mou; without, they fear the strength of Wu, Chu, Huaiyang, Langye, Qi, and Dai." },
  { zh: "方今高帝子，獨淮南王與大王。", literal: "Among the High Emperor's sons today, only the King of Huainan and Your Majesty.", idiomatic: "Among the High Emperor's sons today, only the King of Huainan and Your Majesty." },
  { zh: "大王又長，賢聖仁孝聞於天下，故大臣因天下之心而欲迎立大王。", literal: "Your Majesty is moreover the eldest; your worth, sagacity, humanity, and filial piety are heard throughout all under Heaven—therefore the great ministers rely on the hearts of all under Heaven and wish to welcome and establish Your Majesty.", idiomatic: "Your Majesty is moreover the eldest; your worth, sagacity, humanity, and filial piety are heard throughout the realm—therefore the great ministers rely on the hearts of the realm and wish to welcome and establish Your Majesty." },
  { zh: "大王勿疑也。", literal: "Your Majesty must not doubt.", idiomatic: "Your Majesty must not doubt." },
  { zh: "」代王報太后計之。", literal: "\" The King of Dai reported to the empress dowager to work out a plan.", idiomatic: "\" The King of Dai reported to the empress dowager to work out a plan." },
  { zh: "猶豫未定，卜之，兆得大橫。", literal: "Still hesitating and undecided, he divined; the omen obtained Great Horizontal.", idiomatic: "Still hesitating and undecided, he divined; the omen obtained Great Horizontal." },
  { zh: "占曰：「大橫庚庚，余為天王，夏啟以光。", literal: "The interpretation said: \"Great Horizontal, geng geng; I become King of Heaven; Xia Qi with brightness.", idiomatic: "The interpretation said: \"Great Horizontal, geng geng; I become King of Heaven; Xia Qi with brightness." },
  { zh: "」代王曰：「寡人固已為王矣，又何王？", literal: "\" The King of Dai said: \"I am already king—what further kinghood?", idiomatic: "\" The King of Dai said: \"I am already king—what further kinghood?\"" },
  { zh: "」卜人曰：「所謂天王者，乃天子也。", literal: "\" The diviner said: \"What is called King of Heaven is in fact the Son of Heaven.", idiomatic: "\" The diviner said: \"What is called King of Heaven is in fact the Son of Heaven." },
  { zh: "」於是代王遣太后弟薄昭往見絳侯，絳侯等具為昭言所以迎立王意。", literal: "\" Thereupon the King of Dai sent the empress dowager's younger brother Bo Zhao to go see the Marquis of Jiang; Bo and the others fully explained to Zhao the reason for welcoming and establishing him as king.", idiomatic: "\" Thereupon the King of Dai sent the empress dowager's younger brother Bo Zhao to see the Marquis of Jiang; Bo and the others fully explained to Zhao the reason for welcoming and establishing him as king." },
  { zh: "薄昭還報曰：「信矣，無可疑者。", literal: "When Bo Zhao returned and reported, he said: \"It is trustworthy; there is nothing to doubt.", idiomatic: "When Bo Zhao returned and reported, he said: \"It is trustworthy; there is nothing to doubt." },
  { zh: "」代王乃笑謂宋昌曰：「果如公言。", literal: "\" The King of Dai then smiled and said to Song Chang: \"It has indeed been as you said.", idiomatic: "\" The King of Dai then smiled and said to Song Chang: \"It has indeed been as you said." },
  { zh: "乃命宋昌參乘，張武等六人乘傳，從詣長安。", literal: "He then ordered Song Chang to ride as companion, Zhang Wu and six others to travel post-haste, and followed to Chang'an.", idiomatic: "He then ordered Song Chang to ride as companion, Zhang Wu and six others to travel post-haste, and followed to Chang'an." },
  { zh: "至高陵，休止，而使宋昌先馳之長安觀變。", literal: "Reaching Gaoling, he stopped to rest and sent Song Chang first to gallop to Chang'an and observe developments.", idiomatic: "Reaching Gaoling, he stopped to rest and sent Song Chang first to gallop to Chang'an and observe developments." },
  { zh: "昌至渭橋，丞相以下皆迎。", literal: "When Chang reached the Wei Bridge, the chancellor and those below all came to welcome him.", idiomatic: "When Chang reached the Wei Bridge, the chancellor and those below all came to welcome him." },
  { zh: "昌還報。", literal: "Chang returned to report.", idiomatic: "Chang returned to report." },
  { zh: "代王馳至渭橋，群臣拜謁稱臣，代王下車答拜。", literal: "The King of Dai galloped to the Wei Bridge; the ministers bowed in audience and styled themselves subjects; the King of Dai descended from the chariot and returned the bows.", idiomatic: "The King of Dai galloped to the Wei Bridge; the ministers bowed in audience and styled themselves subjects; the King of Dai descended from the chariot and returned the bows." },
  { zh: "太尉勃進曰：「願請間。", literal: "Grand Commandant Bo advanced and said: \"I wish to request a private word.", idiomatic: "Grand Commandant Bo advanced and said: \"I wish to request a private word." },
  { zh: "」宋昌曰：「所言公，公言之；", literal: "\" Song Chang said: \"What you would speak is public—speak it publicly;", idiomatic: "\" Song Chang said: \"What you would speak is public—speak it publicly;" },
  { zh: "所言私，王者無私。", literal: "what is private, a king has no private affairs.", idiomatic: "what is private, a king has no private affairs." },
  { zh: "」太尉乃跪上天子璽、符。", literal: "\" The Grand Commandant then knelt and presented the Son of Heaven's seal and tally.", idiomatic: "\" The Grand Commandant then knelt and presented the Son of Heaven's seal and tally." },
  { zh: "代王謝曰：「至代邸而議之。", literal: "The King of Dai declined, saying: \"Let us deliberate at the lodging for Dai.", idiomatic: "The King of Dai declined: \"Let us deliberate at the lodging for Dai." },
  { zh: "後九月，己酉晦，代王至長安，舍代邸，群臣從至邸。", literal: "In the intercalary ninth month, on jiyou, the last day of the month, the King of Dai reached Chang'an, lodged at the lodging for Dai, and the ministers followed him to the lodging.", idiomatic: "In the intercalary ninth month, on jiyou, the last day of the month, the King of Dai reached Chang'an, lodged at the lodging for Dai, and the ministers followed him to the lodging." },
  { zh: "丞相陳平等皆再拜言曰：「子弘等皆非孝惠子，不當奉宗廟。", literal: "Chancellor Chen Ping and all twice bowed and said: \"Hong and the others are none of them sons of Emperor Xiaohui and ought not to tend the ancestral temples.", idiomatic: "Chancellor Chen Ping and all twice bowed and said: \"Hong and the others are none of them sons of Emperor Xiaohui and ought not to tend the ancestral temples." },
  { zh: "大王，高帝長子，宜為嗣。", literal: "Your Majesty, eldest son of the High Emperor, should be the heir.", idiomatic: "Your Majesty, eldest son of the High Emperor, should be the heir." },
  { zh: "願大王即天子位。", literal: "We wish Your Majesty to assume the Son of Heaven's place at once.", idiomatic: "We wish Your Majesty to assume the Son of Heaven's place at once." },
  { zh: "」代王西鄉讓者三，南鄉讓者再，遂即天子位。", literal: "\" The King of Dai declined facing west three times, declined facing south twice, and then assumed the Son of Heaven's place.", idiomatic: "\" The King of Dai declined facing west three times, declined facing south twice, and then assumed the Son of Heaven's place." },
  { zh: "群臣以禮次侍。", literal: "The ministers waited in attendance according to ritual order.", idiomatic: "The ministers waited in attendance according to ritual order." },
  { zh: "東牟侯興居曰：「誅呂氏，臣無功，請得除宮。", literal: "Marquis of Dongmou Xingju said: \"In executing the house of Lü, your servant had no merit; I request to be allowed to clear the palace.", idiomatic: "Marquis of Dongmou Xingju said: \"In executing the house of Lü, your servant had no merit; I request to be allowed to clear the palace." },
  { zh: "」乃與太僕汝陰侯滕公入宮，前謂少帝曰：「足下非劉氏子，不當立！", literal: "\" He then entered the palace with Grand Coachman Marquis of Ruyin Teng Gong, went forward and said to the Young Emperor: \"Your Excellency are not of the house of Liu and ought not to be enthroned!", idiomatic: "\" He then entered the palace with Grand Coachman Marquis of Ruyin Teng Gong, went forward and said to the Young Emperor: \"Your Excellency are not of the house of Liu and ought not to be enthroned!\"" },
  { zh: "」乃顧麾左右執戟者掊兵罷去；", literal: "\" Then he turned and gestured to those at the left and right holding halberds to cast aside weapons and withdraw;", idiomatic: "\" Then he turned and gestured to those at the left and right holding halberds to cast aside weapons and withdraw;" },
  { zh: "有數人不肯去兵，宦者令張釋諭告，亦去兵。", literal: "several men would not lay down weapons; Chamberlain Zhang Shizhi was ordered to announce, and they too laid down weapons.", idiomatic: "several men would not lay down weapons; Chamberlain Zhang Shizhi was ordered to announce, and they too laid down weapons." },
  { zh: "滕公乃召乘輿車載少帝出。", literal: "Teng Gong then summoned the imperial carriage to carry the Young Emperor out.", idiomatic: "Teng Gong then summoned the imperial carriage to carry the Young Emperor out." },
  { zh: "少帝曰：「欲將我安之乎？", literal: "The Young Emperor said: \"Where do you mean to take me?", idiomatic: "The Young Emperor said: \"Where do you mean to take me?\"" },
  { zh: "」滕公曰：「出就舍。", literal: "\" Teng Gong said: \"Go out to the lodging.", idiomatic: "\" Teng Gong said: \"Go out to the lodging." },
  { zh: "」舍少府。", literal: "\" He lodged him at the Minor Treasury.", idiomatic: "\" He lodged him at the Minor Treasury." },
  { zh: "乃奉天子法駕迎代王於邸，報曰：「宮謹除。", literal: "Then with the Son of Heaven's formal equipage he welcomed the King of Dai from the lodging and reported: \"The palace has been carefully cleared.", idiomatic: "Then with the Son of Heaven's formal equipage he welcomed the King of Dai from the lodging and reported: \"The palace has been carefully cleared." },
  { zh: "」代王即夕入未央宮。", literal: "\" The King of Dai that evening entered Weiyang Palace.", idiomatic: "\" The King of Dai that evening entered Weiyang Palace." },
  { zh: "有謁者十人持戟衛端門，曰：「天子在也，足下何為者而入？", literal: "Ten chamberlains holding halberds guarded the main gate, saying: \"The Son of Heaven is within; what are Your Excellency doing entering?", idiomatic: "Ten chamberlains holding halberds guarded the main gate: \"The Son of Heaven is within; what are Your Excellency doing entering?\"" },
  { zh: "」代王乃謂太尉。", literal: "\" The King of Dai thereupon spoke to the Grand Commandant.", idiomatic: "\" The King of Dai thereupon spoke to the Grand Commandant." },
  { zh: "太尉往諭，謁者十人皆掊兵而去，代王遂入。", literal: "The Grand Commandant went to announce; the ten chamberlains all cast aside weapons and left; the King of Dai then entered.", idiomatic: "The Grand Commandant went to announce; the ten chamberlains all cast aside weapons and left; the King of Dai then entered." },
  { zh: "夜，拜宋昌為衛將軍，鎮撫南北軍；", literal: "At night, Song Chang was appointed General of the Guard, pacifying the Northern and Southern Armies;", idiomatic: "At night, Song Chang was appointed General of the Guard, pacifying the Northern and Southern Armies;" },
  { zh: "以張武為郎中令，行殿中。", literal: "Zhang Wu was made Gentlemen-of-the-Palace and patrolled within the palace halls.", idiomatic: "Zhang Wu was made Gentlemen-of-the-Palace and patrolled within the palace halls." },
  { zh: "有司分部誅滅梁、淮陽、恆山王及少帝於邸。", literal: "The relevant officials in divisions executed the kings of Liang, Huaiyang, and Hengshan and the Young Emperor at their lodging.", idiomatic: "The relevant officials in divisions executed the kings of Liang, Huaiyang, and Hengshan and the Young Emperor at their lodging." },
  { zh: "文帝還坐前殿，夜，下詔書赦天下。", literal: "Emperor Wen returned and took his seat in the front hall; at night he issued an edict amnestying all under Heaven.", idiomatic: "Emperor Wen returned and took his seat in the front hall; at night he issued an edict amnestying the realm." },
  { zh: "1冬，十月，庚戌，徙琅邪王澤為燕王；", literal: "In winter of year 1, the tenth month, on gengxu, King Ze of Langye was moved to be King of Yan;", idiomatic: "In winter of the first year, in the tenth month, on the day gengxu, King Ze of Langye was transferred to be King of Yan;" },
  { zh: "封趙幽王子遂為趙王。", literal: "King You of Zhao's son Sui was enfeoffed as King of Zhao.", idiomatic: "King You of Zhao's son Sui was enfeoffed as King of Zhao." },
  { zh: "----2陳平謝病。", literal: "----2 Chen Ping declined on grounds of illness.", idiomatic: "----2 Chen Ping declined office on grounds of illness." },
  { zh: "上問之，平曰：「高祖時，勃功不如臣，及誅諸呂，臣功亦不如勃，願以右丞相讓勃。", literal: "The Emperor questioned him; Ping said, “In Gaozu's time Bo's merit was not as great as mine, and in executing the Lü clan my merit was also not as great as Bo's; I wish to yield the right chancellorship to Bo.", idiomatic: "The Emperor asked him; Chen Ping said, “Under Gaozu, Bo's merit was less than mine, and in executing the Lü clan mine was also less than his; I wish to yield the right chancellorship to Bo." },
  { zh: "」十一月，辛巳，上徙平為左丞相，太尉勃為右丞相，大將軍灌嬰為太尉。", literal: "” In the eleventh month, on xinsi, the Emperor moved Ping to left chancellor, Grand Commandant Bo to right chancellor, and Grand General Guan Ying to grand commandant.", idiomatic: "” In the eleventh month, on xinsi, the Emperor made Chen Ping left chancellor, Grand Commandant Zhou Bo right chancellor, and Grand General Guan Ying grand commandant." },
  { zh: "諸呂所奪齊、楚故地，皆復與之。", literal: "The former lands of Qi and Chu seized by the Lü clan were all restored to them.", idiomatic: "The former Qi and Chu territories seized by the Lü clan were all restored." },
  { zh: "----3論誅諸呂功，右丞相勃以下益戶、賜金各有差。", literal: "----3 In assessing merit for executing the Lü clan, from Right Chancellor Bo downward households were increased and gold bestowed, each according to rank.", idiomatic: "----3 When rewards were apportioned for executing the Lü clan, from Right Chancellor Bo downward each received added households and gold according to rank." },
  { zh: "絳侯朝罷趨出，意得甚。", literal: "The Marquis of Jiang, after court was dismissed, hurried out, greatly pleased with himself.", idiomatic: "After court the Marquis of Jiang hurried out, looking very pleased with himself." },
  { zh: "上禮之恭，常目送之。", literal: "The Emperor treated him with respect and often saw him off with his gaze.", idiomatic: "The Emperor treated him with deference and often watched him leave." },
  { zh: "郎中安陵袁盎諫曰：「諸呂悖逆，大臣相與共誅之。", literal: "Palace Gentleman Yuan Ang of Anling remonstrated, saying, “The Lü clan were rebellious; the great ministers together executed them.", idiomatic: "Palace Gentleman Yuan Ang of Anling remonstrated: “The Lü clan rebelled and the great ministers joined to execute them." },
  { zh: "是時丞相為太尉，本兵柄，適會其成功。", literal: "At that time the chancellor was grand commandant and originally held military authority; he happened to coincide with its success.", idiomatic: "At that time the chancellor had been grand commandant and already held military authority; he simply happened to be there when it succeeded." },
  { zh: "今丞相如有驕主色，陛下謙讓。", literal: "Now if the chancellor shows the air of a proud master while Your Majesty is deferential,", idiomatic: "Now if the chancellor acts like a proud master while Your Majesty defers to him," },
  { zh: "臣主失禮，竊為陛下弗取也！", literal: "minister and lord lose propriety—I privately deem this unworthy for Your Majesty!", idiomatic: "lord and minister lose all propriety—I cannot think this fitting for Your Majesty!" },
  { zh: "」後朝，上益莊，丞相益畏。", literal: "” Afterward at court the Emperor grew more stern and the chancellor more fearful.", idiomatic: "” After that at court the Emperor grew sterner and the chancellor more afraid." },
  { zh: "----4十二月，詔曰：「法者，治之正也。", literal: "----4 In the twelfth month an edict said, “Law is the straightedge of governance.", idiomatic: "----4 In the twelfth month an edict said, “Law is the straightedge of rule." },
  { zh: "今犯法已論，而使無罪之父母、妻子、同產坐之，及為收帑，朕甚不取！", literal: "Now when one who violated the law has already been judged, yet innocent parents, wife and children, and household members of the same estate are made to share guilt, and there is confiscation of kin into servitude—We greatly disapprove!", idiomatic: "When the guilty have already been sentenced, yet innocent parents, wives and children, and household kin are punished with them, and families are confiscated into servitude—We cannot accept this!" },
  { zh: "其除收帑諸相坐律令。", literal: "Let the statutes on confiscation of kin and collective punishment be abolished.", idiomatic: "Abolish the statutes on confiscation of kin and collective punishment." },
  { zh: "」----5春，正月，有司請蚤建太子。", literal: "” ----5 In spring, the first month, the responsible officials asked to establish the crown prince early.", idiomatic: "” ----5 In spring, the first month, officials asked that the crown prince be established at once." },
  { zh: "上曰；", literal: "The Emperor said;", idiomatic: "The Emperor said;" },
  { zh: "「朕既不德，縱不能博求天下賢聖有德之人而禪天下焉，而曰豫建太子，是重吾不德也。", literal: "“We lack virtue; even if We cannot broadly seek worthy and sage men of virtue throughout the realm and yield the realm to them, yet to speak of establishing the crown prince in advance is to double Our want of virtue.", idiomatic: "“I lack virtue; even if I cannot seek out worthy and sage men throughout the realm and yield the throne to one of them, to speak of establishing an heir in advance only doubles my want of virtue." },
  { zh: "其安之！", literal: "Let the matter rest!", idiomatic: "Let the matter rest!" },
  { zh: "」有司曰：「豫建太子，所以重宗廟、社稷，不忘天下也。", literal: "” The officials said, “Establishing the crown prince in advance is to give weight to the ancestral temple and altars of soil and grain and not forget the realm.", idiomatic: "” The officials said, “Establishing an heir in advance gives weight to the ancestral temple and altars of state and shows that the realm is not forgotten." },
  { zh: "」上曰：「楚王，季父也；", literal: "” The Emperor said, “The King of Chu is Our uncle;", idiomatic: "” The Emperor said, “The King of Chu is my uncle;" },
  { zh: "吳王，兄也；", literal: "the King of Wu is Our elder brother;", idiomatic: "the King of Wu is my elder brother;" },
  { zh: "淮南王，弟也，豈不豫哉？", literal: "the King of Huainan is Our younger brother—are they not already in the succession?", idiomatic: "the King of Huainan is my younger brother—are they not already in line?" },
  { zh: "今不選舉焉，而曰必子，人其以朕為忘賢有德者而專於子，非所以憂天下也！", literal: "Now not to choose among them but to say it must be a son—men will take Us as forgetting the worthy and virtuous and fixating on Our son; this is not how to care for the realm!", idiomatic: "If I do not choose among them but insist it must be a son, people will think I have forgotten the worthy and virtuous and fix on my own son—this is not how to care for the realm!" },
  { zh: "」有司固請曰：「古者殷、周有國，治安皆千餘歲，用此道也。", literal: "” The officials pressed their request, saying, “In antiquity Yin and Zhou held their states and peace and order each lasted more than a thousand years by using this way.", idiomatic: "” The officials pressed on: “In antiquity Yin and Zhou each held their states in peace for more than a thousand years by this very method." },
  { zh: "立嗣必子，所從來遠矣。", literal: "Establishing the succession must be through a son—the origin of this is far back.", idiomatic: "The heir must be a son—a practice of very ancient standing." },
  { zh: "高帝平天下為太祖，子孫繼嗣世世不絕，今釋宜建而更選於諸侯及宗室，非高帝之志也。", literal: "Gaozu settled the realm and became Grand Ancestor; descendants succeeding in generation after generation without end—now to set aside what ought to be established and instead choose anew among feudal lords and the imperial clan is not Gaozu's intent.", idiomatic: "Gaozu pacified the realm as Grand Ancestor so that descendants might succeed generation after generation without end; to set aside what ought to be done and choose anew among feudal lords and the imperial clan is not Gaozu's intent." },
  { zh: "更議不宜。", literal: "Further discussion is not fitting.", idiomatic: "Further debate is out of place." },
  { zh: "子啟最長，純厚慈仁，請建以為太子。", literal: "The son Qi is eldest, pure, generous, and benevolent—I ask that he be established as crown prince.", idiomatic: "His son Qi is the eldest, pure, generous, and benevolent; we ask that he be made crown prince." },
  { zh: "」上乃許之。", literal: "” The Emperor then assented.", idiomatic: "” The Emperor then agreed." },
  { zh: "----6三月，立太子母竇氏為皇后。", literal: "----6 In the third month the crown prince's mother, the Dou clan, was established as empress.", idiomatic: "----6 In the third month the crown prince's mother, Lady Dou, was made empress." },
  { zh: "皇后，清河觀津人。", literal: "The empress was a native of Guanjin in Qinghe.", idiomatic: "The empress was from Guanjin in Qinghe commandery." },
  { zh: "有弟廣國，字少君，幼為人所略賣，傳十餘家，聞-{竇后}-立，乃上書自陳。", literal: "She had a younger brother Guangguo, styled Shaojun, who in youth was kidnapped and sold, passing through more than ten households; hearing that -{竇后}- had been established, he then submitted a memorial stating his case.", idiomatic: "She had a younger brother Guangguo, styled Shaojun, who as a child was kidnapped and sold through more than ten households; when he heard Empress Dou had been established, he submitted a memorial identifying himself." },
  { zh: "召見，驗問，得實，乃厚賜田宅、金錢，與兄長君家於長安。", literal: "Summoned and received, questioned and verified—the facts were true; he was then richly granted fields, dwellings, and gold and silver, and together with his elder brother Changjun was housed in Chang'an.", idiomatic: "He was summoned, questioned, and the facts verified; he received rich grants of land, houses, and money, and he and his elder brother Changjun were given residences in Chang'an." },
  { zh: "絳侯、灌將軍等曰：「吾屬不死，命乃且縣此兩人。", literal: "The Marquis of Jiang, General Guan, and others said, “If our kind do not die, our lives still hang by these two men.", idiomatic: "The Marquis of Jiang, General Guan, and others said, “If we are not to die, our lives still hang by these two." },
  { zh: "兩人所出微，不可不為擇師傅、賓客；", literal: "The two men's origins are humble; tutors and retainers must be chosen for them;", idiomatic: "Both come from humble origins; tutors and retainers must be chosen for them;" },
  { zh: "又復效呂氏，大事也！", literal: "if they again imitate the Lü clan, it will be a great matter!", idiomatic: "if they imitate the Lü clan again, it will be a grave matter!" },
  { zh: "」於是乃選士之有節行者與居。", literal: "” Thereupon men of learning with integrity in conduct were chosen to dwell with them.", idiomatic: "” Scholars of proven integrity were then chosen to live with them." },
  { zh: "竇長君、少君由此為退讓君子，不敢以尊貴驕人。", literal: "Dou Changjun and Shaojun thereby became modest gentlemen and did not dare to act proudly toward others on account of their exalted rank.", idiomatic: "Dou Changjun and Shaojun thereby became modest gentlemen and did not presume on their rank to treat others arrogantly." },
  { zh: "----7詔振貸鰥、寡、孤、獨、窮困之人。", literal: "----7 An edict granted relief loans to widowers, widows, orphans, solitaries, and those in destitution.", idiomatic: "----7 An edict ordered relief for widowers, widows, orphans, the childless elderly, and the destitute." },
  { zh: "又令：「八十已上，月賜米、肉、酒；", literal: "It also ordered: “Those eighty and above shall monthly receive rice, meat, and wine;", idiomatic: "It also ordered: “Those eighty and above shall receive monthly allotments of rice, meat, and wine;" },
  { zh: "九十已上，加賜帛、絮。", literal: "those ninety and above shall additionally receive silk and wadding.", idiomatic: "those ninety and above shall additionally receive silk and cotton wadding." },
  { zh: "賜物當稟鬻米者，長吏閱視，丞若尉致；", literal: "Where gifts should be reported and converted to rice for sale, chief officials shall inspect; the assistant or commandant shall deliver;", idiomatic: "Where stipends are to be reported and converted to rice, chief officials shall inspect and the assistant or commandant shall deliver;" },
  { zh: "不滿九十，嗇夫、令史致；", literal: "those not yet ninety, the district clerk and recorder shall deliver;", idiomatic: "for those under ninety, the district clerk and recorder shall deliver;" },
  { zh: "二千石遣都吏循行，不稱者督之。", literal: "officials of two thousand dan shall send capital clerks to tour and inspect, and supervise those who fall short.", idiomatic: "officials of two thousand dan shall send inspectors on circuit and hold accountable any who fail to comply." },
  { zh: "」----8楚元王交薨。", literal: "” ----8 King Yuan of Chu, Jiao, died.", idiomatic: "” ----8 King Yuan of Chu, Liu Jiao, died." },
  { zh: "----9夏，四月，齊、楚地震，二十九山同日崩，大水潰出。", literal: "----9 In summer, the fourth month, Qi and Chu had earthquakes; twenty-nine mountains on the same day collapsed and great floods burst forth.", idiomatic: "----9 In summer, the fourth month, Qi and Chu were shaken by earthquakes; twenty-nine mountains collapsed on the same day and great floods burst out." },
  { zh: "----10時有獻千里馬者。", literal: "----10 At that time someone presented a horse of a thousand li.", idiomatic: "----10 At that time someone presented a thousand-li horse." },
  { zh: "帝曰：「鸞旗在前，屬車在後，吉行日五十里，師行三十里。", literal: "The Emperor said, “The imperial escort banners go before and the attendant chariots follow behind; on an auspicious journey one covers fifty li a day, on a military march thirty li.", idiomatic: "The Emperor said, “Imperial banners go before and attendant chariots follow; on a ceremonial journey we cover fifty li a day, on campaign thirty." },
  { zh: "朕乘千里馬，獨先安之？", literal: "If We ride a horse of a thousand li, where would We go ahead alone?", idiomatic: "If I ride a thousand-li horse, where would I go ahead alone?" },
  { zh: "」於是還其馬，與道里費，而下詔曰：「朕不受獻也。", literal: "” Thereupon he returned the horse, gave traveling expenses, and issued an edict saying, “We do not accept presentations.", idiomatic: "” He returned the horse, gave traveling expenses, and issued an edict: “I do not accept presentations." },
  { zh: "其令四方毋求來獻。", literal: "Let the four quarters be ordered not to seek to come with offerings.", idiomatic: "Let the four quarters be ordered not to come bearing tribute." },
  { zh: "」----11帝既施惠天下，諸侯、四夷遠近歡洽。", literal: "” ----11 Once the Emperor had extended favor throughout the realm, feudal lords and the four Yi near and far were harmonious.", idiomatic: "” ----11 Once the Emperor had extended his grace throughout the realm, feudal lords and the four quarters near and far were at ease." },
  { zh: "乃修代來功，封宋昌為壯武侯。", literal: "He then reviewed merit from coming from Dai and enfeoffed Song Chang as Marquis of Zhuangwu.", idiomatic: "He then reviewed those who had aided his coming from Dai and enfeoffed Song Chang as Marquis of Zhuangwu." },
  { zh: "----12帝益明習國家事。", literal: "----12 The Emperor grew ever clearer and practiced in state affairs.", idiomatic: "----12 The Emperor grew ever more skilled in affairs of state." },
  { zh: "朝而問右丞相勃曰：「天下一歲決獄幾何？", literal: "At court he asked Right Chancellor Bo, saying, “Throughout the realm, how many cases are decided in a year?", idiomatic: "At court he asked Right Chancellor Zhou Bo: “How many cases are decided throughout the realm in a year?" },
  { zh: "」勃謝不知。", literal: "” Bo apologized that he did not know.", idiomatic: "” Bo apologized that he did not know." },
  { zh: "又問：「一歲錢穀出入幾何？", literal: "He asked again, “How much money and grain go in and out in a year?", idiomatic: "He asked again: “How much money and grain enter and leave the treasury in a year?" },
  { zh: "」勃又謝不知，惶愧，汗出沾背。", literal: "” Bo again apologized that he did not know, fearful and ashamed, sweat soaking his back.", idiomatic: "” Bo again said he did not know, fearful and ashamed, sweat soaking his back." },
  { zh: "上問左丞相平。", literal: "The Emperor asked Left Chancellor Ping.", idiomatic: "The Emperor asked Left Chancellor Chen Ping." },
  { zh: "平曰：「有主者。", literal: "Ping said, “There are those in charge.", idiomatic: "Chen Ping said, “There are officials in charge of that." },
  { zh: "」上曰：「主者謂誰？", literal: "” The Emperor said, “Whom do you mean by those in charge?", idiomatic: "” The Emperor said, “Who is in charge?" },
  { zh: "」曰：「陛下即問決獄，責廷尉；", literal: "” He said, “If Your Majesty asks about deciding cases, hold the commandant of justice responsible;", idiomatic: "” He said, “If Your Majesty asks about cases, hold the commandant of justice responsible;" },
  { zh: "問錢穀，責治粟內史。", literal: "if you ask about money and grain, hold the superintendent of grain within the passes responsible.", idiomatic: "if about money and grain, hold the superintendent of grain responsible." },
  { zh: "」上曰：「苟各有主者，而君所主者何事也？", literal: "” The Emperor said, “If each has its charge, what affairs does the lord chancellor himself oversee?", idiomatic: "” The Emperor said, “If each has its officer, what do you yourself oversee?" },
  { zh: "」平謝曰：「陛下不知其駑下，使待罪宰相。", literal: "” Ping apologized, saying, “Your Majesty does not know my incompetence and has made me serve as chancellor while awaiting punishment.", idiomatic: "” Chen Ping apologized: “Your Majesty does not know how incompetent I am and has made me serve as chancellor." },
  { zh: "宰相者，上佐天子，理陰陽，順四時；", literal: "The chancellor assists the Son of Heaven above, harmonizes yin and yang, and accords with the four seasons;", idiomatic: "The chancellor assists the Son of Heaven above, harmonizes yin and yang, and accords with the four seasons;" },
  { zh: "下遂萬物之宜；", literal: "below he carries through what is fitting for the ten thousand things;", idiomatic: "below he brings the ten thousand things to their proper course;" },
  { zh: "外鎮撫四夷諸侯；", literal: "externally he pacifies the four Yi and feudal lords;", idiomatic: "externally he pacifies the four quarters and feudal lords;" },
  { zh: "內親附百姓，使卿大夫各得任其職焉。", literal: "internally he draws the people close and causes ministers and grandees each to fulfill his charge.", idiomatic: "internally he draws the people close and sees that ministers and grandees each fulfill his charge." },
  { zh: "」帝乃稱善。", literal: "” The Emperor then praised it as good.", idiomatic: "” The Emperor praised this." },
  { zh: "右丞相大慚，出而讓陳平曰：「君獨不素教我對！", literal: "The right chancellor was greatly ashamed; going out he reproached Chen Ping, saying, “Did you alone never teach me how to answer!", idiomatic: "The right chancellor was deeply ashamed; leaving court he reproached Chen Ping: “Why did you never teach me how to answer!" },
  { zh: "」陳平笑曰：「君居其位，不知其任邪？", literal: "” Chen Ping laughed and said, “You occupy the post—do you not know its charge?", idiomatic: "” Chen Ping laughed: “You hold the post—do you not know its duties?" },
  { zh: "且陛下即問長安中盜賊數，君欲強對邪？", literal: "Moreover, if Your Majesty were to ask the number of thieves in Chang'an, would you force an answer?", idiomatic: "And if Your Majesty asked how many thieves there are in Chang'an, would you force an answer?" },
  { zh: "」於是絳侯自知其能不如平遠矣。", literal: "” Thereupon the Marquis of Jiang knew that his ability fell far short of Ping's.", idiomatic: "” Then the Marquis of Jiang knew his ability fell far short of Chen Ping's." },
  { zh: "居頃之，人或說勃曰：「君既誅諸呂，立代王，威震天下。", literal: "Before long someone urged Bo, saying, “You executed the Lü clan and established the King of Dai; your authority shakes the realm.", idiomatic: "Before long someone urged Zhou Bo: “You executed the Lü clan and established the King of Dai; your authority shakes the realm." },
  { zh: "而君受厚賞，處尊位，久之，即禍及身矣。", literal: "Yet you received rich rewards and occupy an exalted post; before long disaster will reach your person.", idiomatic: "Yet you have received rich rewards and hold an exalted post; before long disaster will reach you." },
  { zh: "」勃亦自危，乃謝病，請歸相印，上許之。", literal: "” Bo also felt himself in peril; he then declined on grounds of illness and asked to return the chancellor's seal, and the Emperor permitted it.", idiomatic: "” Zhou Bo also felt endangered; he declined on grounds of illness and asked to return the chancellor's seal, and the Emperor agreed." },
  { zh: "秋，八月，辛未，右丞相勃免，左丞相平專為丞相。", literal: "In autumn, the eighth month, on xinwei, Right Chancellor Bo was dismissed and Left Chancellor Ping alone became chancellor.", idiomatic: "In autumn, the eighth month, on xinwei, Right Chancellor Zhou Bo was dismissed and Left Chancellor Chen Ping became sole chancellor." },
  { zh: "----13初，隆慮侯灶擊南越，會暑濕，士卒大疫，兵不能隃領。", literal: "----13 At first the Marquis of Longlü, Zao, attacked the Southern Yue; encountering heat and dampness, the troops suffered a great epidemic and the army could not cross the passes.", idiomatic: "----13 Earlier, when the Marquis of Longlü, Zao, attacked the Southern Yue, heat and damp brought a great epidemic among the troops and the army could not cross the frontier passes." },
  { zh: "歲餘，-{高后}-崩，即罷兵。", literal: "After more than a year -{高后}- died and the troops were at once withdrawn.", idiomatic: "After more than a year Empress Dowager Gao died and the army was withdrawn." },
  { zh: "趙佗因此以兵威財物賂遺閩越、西甌、駱，役屬焉。", literal: "Zhao Tuo thereby used military might and goods as bribes to present to Min Yue, Western Ou, and the Luo, and made them subject to his service.", idiomatic: "Zhao Tuo then used military might and gifts to win over Min Yue, Western Ou, and the Luo peoples and bring them under his rule." },
  { zh: "東西萬餘里，乘黃屋左纛，稱制與中國侔。", literal: "East and west more than ten thousand li, he rode the yellow canopy with the left banner and styled himself emperor on a par with China.", idiomatic: "His domain stretched more than ten thousand li east to west; he rode the yellow canopy with the left banner and styled himself emperor on a par with China." },
  { zh: "帝乃為佗親塚在真定者置守邑，歲時奉祀；", literal: "The Emperor then for Tuo's ancestral tombs at Zhending established guard districts and seasonal sacrifices;", idiomatic: "The Emperor then established guard districts for Zhao Tuo's ancestral tombs at Zhending and ordered seasonal sacrifices;" },
  { zh: "召其昆弟，尊官、厚賜寵之。", literal: "summoned his brothers, gave them honored offices, and richly favored them.", idiomatic: "summoned his brothers, gave them honored posts, and richly favored them." },
  { zh: "復使陸賈使南越，賜佗書曰：「朕，高皇帝側室之子也，棄外，奉北籓於代。", literal: "He again sent Lu Jia as envoy to the Southern Yue and bestowed on Tuo a letter saying, “We are a son of Gaozu by a side chamber, set aside abroad, and received the northern fief at Dai.", idiomatic: "He again sent Lu Jia as envoy to the Southern Yue with a letter to Zhao Tuo: “I am a son of Gaozu by a concubine, set aside in the borderlands, and received the northern fief at Dai." },
  { zh: "道里遼遠，壅蔽樸愚，未嘗致書。", literal: "The roads are far and communication blocked; crude and foolish, We have never sent a letter.", idiomatic: "The roads are distant and I was cut off in my simplicity; I have never before sent you word." },
  { zh: "高皇帝棄群臣，孝惠皇帝即世；", literal: "Gaozu left his ministers; Emperor Xiaohui passed from the world;", idiomatic: "Gaozu left his ministers; Emperor Xiaohui passed away;" },
  { zh: "-{高后}-自臨事，不幸有疾，諸呂為變，賴功臣之力，誅之已畢，朕以王、侯、吏不釋之故，不得不立。", literal: "-{高后}- herself oversaw affairs; unfortunately she fell ill and the Lü clan made trouble; relying on the merit of the great ministers they were executed to completion; We, because kings, marquises, and officials would not be released, had no choice but to take the throne.", idiomatic: "Empress Dowager Gao herself held power; she fell ill and the Lü clan rebelled; thanks to the great ministers they were executed to the last; because kings, marquises, and officials would not be reassured, I had no choice but to ascend." },
  { zh: "今即位。", literal: "Now We have taken the throne.", idiomatic: "I have now taken the throne." },
  { zh: "乃者聞王遺將軍隆慮侯書，求親昆弟，請罷長沙兩將軍。", literal: "Recently We heard that Your Majesty sent a letter to General the Marquis of Longlü, seeking your kin among brothers and asking that the two generals of Changsha be dismissed.", idiomatic: "Recently I heard that you sent a letter to General the Marquis of Longlü, seeking your brothers and asking that the two Changsha generals be dismissed." },
  { zh: "朕以王書罷將軍博陽侯；", literal: "We, on account of Your Majesty's letter, dismissed General the Marquis of Boyang;", idiomatic: "At your request I have dismissed General the Marquis of Boyang;" },
  { zh: "親昆弟在真定者，已遣人存問，修治先人塚。", literal: "kinsmen and brothers at Zhending have already had men sent to inquire after them and repair the ancestral tombs.", idiomatic: "your brothers at Zhending have already been visited and your ancestral tombs repaired." },
  { zh: "前日聞王發兵於邊，為寇災不止。", literal: "The other day We heard that Your Majesty raised troops on the border and raiding disasters have not ceased.", idiomatic: "The other day I heard you had raised troops on the border and raids have not ceased." },
  { zh: "當其時，長沙苦之，南郡尤甚。", literal: "At that time Changsha suffered bitterly and Nan commandery suffered most of all.", idiomatic: "At that time Changsha suffered bitterly and Nan commandery most of all." },
  { zh: "雖王之國，庸獨利乎！", literal: "Though it is Your Majesty's state, could it alone profit?", idiomatic: "Though it is your own kingdom, can it alone benefit?" },
  { zh: "必多殺士卒，傷良將吏，寡人之妻，孤人之子，獨人父母，得一亡十，朕不忍為也。", literal: "It must multiply the killing of soldiers, wound good generals and officials, make men's wives widows, orphan men's sons, and bereave men's parents—for one gain ten losses; We cannot bear to do it.", idiomatic: "It must multiply the killing of soldiers, wound good commanders, widow wives, orphan sons, and bereave parents—for one gain, ten losses; I cannot bear to do it." },
  { zh: "朕欲定地犬牙相入者，以問吏，吏曰：『高皇帝所以介長沙土也。", literal: "We wish to fix boundaries where territories interlock like a dog's teeth and asked the officials; the officials said, ‘This is how Gaozu divided the soil of Changsha.", idiomatic: "I wish to fix the boundaries where our lands interlock like dog's teeth and asked the officials; they said, ‘This is how Gaozu divided the territory of Changsha." },
  { zh: "』朕不得擅變焉。", literal: "’ We cannot change it on Our own authority.", idiomatic: "’ I cannot change that on my own authority." },
  { zh: "今得王之地，不足以為大；", literal: "Now to gain Your Majesty's territory would not suffice to make one great;", idiomatic: "To take your territory would not make me great;" },
  { zh: "得王之財，不足以為富。", literal: "to gain Your Majesty's wealth would not suffice to make one rich.", idiomatic: "to take your wealth would not make me rich." },
  { zh: "服領以南，王自治之。", literal: "South of Fuling Pass, Your Majesty may govern on your own.", idiomatic: "South of Fuling Pass you may govern on your own." },
  { zh: "雖然，王之號為帝。", literal: "Nevertheless, Your Majesty's title is emperor.", idiomatic: "Nevertheless, your title is still emperor." },
  { zh: "兩帝並立，亡一乘之使以通其道，是爭也；", literal: "If two emperors stand side by side yet lack even a one-horse envoy to keep a road open between them, that is contention;", idiomatic: "If two emperors stand together yet lack even a one-horse messenger to keep the road open between them, that is contention;" },
  { zh: "爭而不讓，仁者不為也。", literal: "to contend and not yield—no benevolent man would do it.", idiomatic: "to contend and not yield—no benevolent man would do it." },
  { zh: "願與王分棄前惡，終今以來，通使如故。", literal: "We wish with Your Majesty equally to cast aside past ill will; from this end forward, to send envoys as of old.", idiomatic: "I wish with you equally to cast aside past ill will; from now on let envoys pass as before." },
  { zh: "賈至南越，南越王恐，頓首謝罪，願奉明詔，長為籓臣，奉貢職。", literal: "When Jia reached the Southern Yue, the King of Southern Yue was afraid; he knocked his head and apologized, willing to receive the bright edict and long be a frontier vassal, fulfilling tribute duties.", idiomatic: "When Lu Jia reached the Southern Yue, the king was afraid; he knocked his head in apology and vowed to obey the imperial edict, remain a frontier vassal forever, and fulfill his tribute duties." },
  { zh: "於是下令國中曰：「吾聞兩雄不俱立，兩賢不並世。", literal: "Thereupon he issued an order in the state, saying, “I have heard that two heroes do not stand together, nor two sages in one age.", idiomatic: "Thereupon he issued an order throughout the state: “I have heard that two heroes do not stand together, nor two sages in one age." },
  { zh: "漢皇帝，賢天子。", literal: "The Han Emperor is a worthy Son of Heaven.", idiomatic: "The Han Emperor is a worthy Son of Heaven." },
  { zh: "自今以來，去帝制、黃屋、左纛。", literal: "From this end forward, abandon the imperial system, yellow canopy, and left banner.", idiomatic: "From now on I shall abandon the imperial title, yellow canopy, and left banner." },
  { zh: "」因為書，稱：「蠻夷大長、老夫臣佗昧死再拜上書皇帝陛下：老夫，故越吏也，高皇帝幸賜臣佗璽，以為南越王。", literal: "” He then composed a letter, styled: “Great chieftain of the barbarian Yi, your old servant Tuo, risking death, twice knocks head and submits this letter to His Majesty the Emperor: I, your old servant, was formerly a Yue official; the High Emperor graciously granted me Tuo a seal and made me King of the Southern Yue.", idiomatic: "” He then wrote a letter styled: “Great chieftain of the barbarians, your old servant Tuo, risking death, twice knocks head and submits this letter to His Majesty the Emperor: I, your old servant, was formerly a Yue official; the High Emperor graciously granted me a seal and made me King of the Southern Yue." },
  { zh: "孝惠皇帝即位，義不忍絕，所以賜老夫者甚厚。", literal: "When Emperor Xiaohui took the throne, in righteousness he could not bear to cut me off, and what he bestowed on me, your old servant, was very generous.", idiomatic: "When Emperor Xiaohui took the throne, in righteousness he could not cut me off, and what he bestowed on your old servant was very generous." },
  { zh: "-{高后}-用事，別異蠻夷，出令曰：『毋與蠻夷越金、鐵、田器、馬、牛、羊。", literal: "-{高后}- held power, treated the barbarian Yi differently, and issued an order, saying, ‘Do not give the barbarian Yi of Yue gold, iron, field tools, horses, cattle, or sheep.", idiomatic: "-{高后}- held power, treated the barbarians differently, and issued an order: ‘Do not give the barbarian Yi of Yue gold, iron, field tools, horses, cattle, or sheep." },
  { zh: "即予，予牡，毋予牝。", literal: "If you give any, give males; do not give females.", idiomatic: "If you give any, give males only; do not give females." },
  { zh: "』老夫處僻，馬、牛、羊齒已長。", literal: "’ Your old servant dwells in a remote place; our horses, cattle, and sheep are already grown.", idiomatic: "’ Your old servant dwells in a remote place; our horses, cattle, and sheep are already fully grown." },
  { zh: "自以祭祀不修，有死罪，使內史籓、中尉高、御史平凡三輩上書謝過，皆不反。", literal: "Thinking ritual sacrifice poorly kept was a capital offense, I sent three parties—the inner secretary Fan, commandant of the guards Gao, and common recorder Ping of the censorate—to submit letters apologizing; none returned.", idiomatic: "Thinking that poorly kept sacrifices were a capital offense, I sent three parties—the inner secretary Fan, the commandant of the guards Gao, and the censorate recorder Ping—to submit letters of apology; none returned." },
  { zh: "又風聞老夫父母墳墓已壞削，兄弟宗族已誅論。", literal: "I also heard on rumor that my parents' tombs had been destroyed and my brothers and clansmen condemned and executed.", idiomatic: "I also heard on rumor that my parents' tombs had been destroyed and my brothers and clansmen condemned and executed." },
  { zh: "吏相與議曰：『今內不得振於漢，外無以自高異。", literal: "Officials discussed among themselves, saying, ‘Now inwardly we cannot gain standing with Han, and outwardly have no way to exalt ourselves differently.", idiomatic: "Officials discussed among themselves: ‘Now inwardly we cannot gain standing with Han, and outwardly have no way to set ourselves apart." },
  { zh: "』故更號為帝，自帝其國，非敢有害於天下。", literal: "’ So we changed our title to emperor and made ourselves emperors in our state—not daring to harm all under Heaven.", idiomatic: "’ So we changed our title to emperor and styled ourselves emperors in our state—not daring to harm all under Heaven." },
  { zh: "高皇后聞之，大怒，削去南越之籍，使使不通。", literal: "When Empress Dowager Gao heard, she was greatly angry, struck Southern Yue from the register, and cut off envoys.", idiomatic: "When Empress Dowager Gao heard, she was greatly angry, struck Southern Yue from the register, and cut off diplomatic contact." },
  { zh: "老夫竊疑長沙王讒臣，故發兵以伐其邊。", literal: "Your old servant privately suspected the King of Changsha had slandered me, so I sent troops to attack his border.", idiomatic: "Your old servant privately suspected the King of Changsha had slandered me, so I sent troops to raid his border." },
  { zh: "老夫處越四十九年，於今抱孫焉。", literal: "Your old servant has dwelt in Yue forty-nine years and now holds a grandchild in his arms.", idiomatic: "Your old servant has dwelt in Yue forty-nine years and now holds a grandchild in his arms." },
  { zh: "然夙興夜寐，寢不安席，食不甘味，目不視靡曼之色，耳不聽鐘鼓之音者，以不得事漢也。", literal: "Yet rising early and sleeping late, bed without peace, food without savor, eyes not viewing gorgeous colors, ears not hearing bells and drums—all because I could not serve Han.", idiomatic: "Yet rising early and sleeping late, with no peace in bed or savor in food, eyes not viewing gorgeous colors, ears not hearing bells and drums—all because I could not serve Han." },
  { zh: "今陛下幸哀憐，復故號，通使漢如故；", literal: "Now Your Majesty has graciously pitied me, restored the old title, and envoys with Han as before;", idiomatic: "Now Your Majesty has graciously pitied me, restored my old title, and envoys pass with Han as before;" },
  { zh: "老夫死，骨不腐。", literal: "when your old servant dies, his bones will not rot away.", idiomatic: "when your old servant dies, his bones will not rot away." },
  { zh: "改號，不敢為帝矣！", literal: "To change our title—I dare not be emperor again!", idiomatic: "To change our title—I dare not be emperor again!”" },
  { zh: "」----14齊哀王襄薨。", literal: "” ----14 King Ai of Qi, Xiang, died.", idiomatic: "” ----14 King Ai of Qi, Liu Xiang, died." },
  { zh: "----15上聞河南守吳公治平為天下第一，召以為廷尉。", literal: "----15 The Emperor heard that Wu Gong, prefect of Henan, in governance and peace ranked first in all under Heaven and summoned him to be commandant of justice.", idiomatic: "----15 The Emperor heard that Wu Gong, prefect of Henan, ranked first in all under Heaven for governance and peace, and summoned him to be commandant of justice." },
  { zh: "吳公薦洛陽人賈誼，帝召以為博士。", literal: "Wu Gong recommended Jia Yi of Luoyang; the Emperor summoned him and made him erudite.", idiomatic: "Wu Gong recommended Jia Yi of Luoyang; the Emperor summoned him and made him an erudite." },
  { zh: "是時賈生年二十餘。", literal: "At that time Master Jia was in his twenties.", idiomatic: "At that time Jia Yi was in his twenties." },
  { zh: "帝愛其辭博，一歲中，超遷至太中大夫。", literal: "The Emperor loved his broad eloquence; within a year he was promoted past regular steps to grand master of the palace.", idiomatic: "The Emperor loved his broad learning; within a year he was promoted past regular steps to grand master of the palace." },
  { zh: "賈生請改正朔，易服色，定官名，興禮樂，以立漢制，更秦法。", literal: "Master Jia asked to correct the calendar beginning, change ceremonial colors, fix official titles, raise ritual and music, establish Han institutions, and reform Qin law.", idiomatic: "Jia Yi asked to correct the calendar, change ceremonial colors, fix official titles, raise ritual and music, establish Han institutions, and reform Qin law." },
  { zh: "帝謙讓未遑也。", literal: "The Emperor modestly deferred—there was as yet no leisure.", idiomatic: "The Emperor modestly deferred; there was as yet no leisure for it." },
  { zh: "----1冬，十月，曲逆獻侯陳平薨。", literal: "----1 In winter, the tenth month, Marquis Xian of Quyu, Chen Ping, died.", idiomatic: "----1 In winter, the tenth month, Marquis Xian of Quyu, Chen Ping, died." },
  { zh: "----2詔列侯各之國，為吏及詔所止者，遣太子。", literal: "----2 An edict: feudal lords each to their states; those serving as officials and those halted by edict should send their heirs.", idiomatic: "----2 An edict ordered feudal lords each to his state; those serving as officials and those held back by edict were to send their heirs." },
  { zh: "----3十一月，乙亥，周勃復為丞相。", literal: "----3 In the eleventh month, on yihai, Zhou Bo again became chancellor.", idiomatic: "----3 In the eleventh month, on yihai, Zhou Bo again became chancellor." },
  { zh: "----4癸卯晦，日有食之。", literal: "----4 On the last day of the month guimao, there was an eclipse of the sun.", idiomatic: "----4 On the last day of the month guimao, there was a solar eclipse." },
  { zh: "詔：「群臣悉思朕之過失及知見之所不及，匄以啟告朕。", literal: "An edict: “Let all ministers reflect on Our faults and what their knowledge and insight fail to reach, and beg to report them to Us.", idiomatic: "An edict: “Let all ministers reflect on my faults and on what their knowledge and insight fail to reach, and beg to report them to me." },
  { zh: "及舉賢良、方正、能直言極諫者，以匡朕之不逮。", literal: "And recommend worthy and upright men able to speak bluntly and remonstrate extremely, to correct Our shortcomings.", idiomatic: "And recommend worthy and upright men able to speak bluntly and remonstrate forcefully, to correct my shortcomings." },
  { zh: "」因各敕以職任，務省繇費以便民，罷衛將軍。", literal: "” Thereupon each was charged with his duties, charged to reduce corvée levies to benefit the people, and the general of the guard was abolished.", idiomatic: "” Thereupon each was charged with his duties, told to reduce corvée levies to benefit the people, and the general of the guard was abolished." },
  { zh: "太僕見馬遺財足，餘皆以給傳置。", literal: "The grand coachman reported surplus horses at the treasury; the remainder were all given to relay stations.", idiomatic: "The grand coachman reported surplus horses in the treasury; the remainder were all assigned to relay stations." },
  { zh: "穎陰侯騎賈山上書言治亂之道曰：", literal: "The Marquis of Yingyin, Jia Shan, submitted a memorial on the Way of order and disorder, saying:", idiomatic: "The Marquis of Yingyin, Jia Shan, submitted a memorial on the way of order and disorder, saying:" },
  { zh: ":「臣聞雷霆之所擊，無不摧折者；", literal: ": “I have heard that what thunderbolts strike, nothing fails to be shattered;", idiomatic: ": “I have heard that what thunderbolts strike, nothing fails to be shattered;" },
  { zh: "萬鈞之所壓，無不糜滅者。", literal: "what ten thousand jun weights press, nothing fails to be ground to dust.", idiomatic: "what ten thousand jun weights press, nothing fails to be ground to dust." },
  { zh: "今人主之威，非特雷霆也；", literal: "Now the lord's majesty is not merely like thunderbolts;", idiomatic: "Now the lord's majesty is not merely like thunderbolts;" },
  { zh: "執重，非特萬鈞也。", literal: "what he grasps is weighty—not merely ten thousand jun.", idiomatic: "what he holds is weighty—not merely ten thousand jun." },
  { zh: "開道而求諫，和顏色而受之，用其言而顯其身，士猶恐懼而不敢自盡；", literal: "He opens the Way and seeks remonstrance, receives it with gentle countenance, uses their words and honors their persons—yet scholars still fear and dare not exhaust themselves;", idiomatic: "He opens the way and seeks remonstrance, receives it with a gentle countenance, uses their words and honors their persons—yet scholars still fear and dare not speak their full mind;" },
  { zh: "又況於縱欲恣暴、惡聞其過乎！", literal: "how much more when one indulges desires, acts willfully and violently, and hates to hear of one's faults!", idiomatic: "how much more when one indulges desire, acts willfully and violently, and hates to hear of one's faults!" },
  { zh: "震之以威，壓之以重，雖有堯、舜之智，孟賁之勇，豈有不摧折者哉！", literal: "Shake them with majesty, press them with weight—even with Yao and Shun's wisdom, Meng Ben's courage, would there be any who are not shattered!", idiomatic: "Shake them with majesty and press them with weight—even with the wisdom of Yao and Shun and the courage of Meng Ben, would any fail to be shattered!" },
  { zh: "如此，則人主不得聞其過，社稷危矣。", literal: "If so, the lord cannot hear his faults and the altars of state are in peril.", idiomatic: "If so, the lord cannot hear his faults and the altars of state are in peril." },
  { zh: ":昔者周蓋千八百國，以九州之民養千八百國之君，君有餘財，民有餘力，而頌聲作。", literal: ": In former times Zhou had perhaps eighteen hundred states; the people of the Nine Provinces supported eighteen hundred lords—the lords had surplus wealth, the people surplus strength, and songs of praise arose.", idiomatic: ": In former times Zhou had perhaps eighteen hundred states; the people of the Nine Provinces supported eighteen hundred lords—the lords had surplus wealth, the people surplus strength, and songs of praise arose." },
  { zh: "秦皇帝以千八百國之民自養，力罷不能勝其役，財盡不能勝其求。", literal: "The Qin Emperor used the people of those eighteen hundred states to nourish himself alone; strength exhausted, they could not bear his corvées; wealth spent, they could not satisfy his demands.", idiomatic: "The First Emperor of Qin used the people of those eighteen hundred states to nourish himself alone; strength exhausted, they could not bear his corvées; wealth spent, they could not satisfy his demands." },
  { zh: "一君之身耳，所自養者馳騁弋獵之娛，天下弗能供也。", literal: "One lord's person—the pleasures he nourished himself with were racing, archery, and hunting—and all under Heaven could not supply them.", idiomatic: "One man's person—the pleasures with which he nourished himself were racing, archery, and hunting—and all under Heaven could not supply them." },
  { zh: "秦皇帝計其功德，度其後嗣世世無窮；", literal: "The First Emperor of Qin reckoned his merit and measured that his descendants for generations without end—", idiomatic: "The First Emperor reckoned his merit and measured that his descendants for generations without end—" },
  { zh: "然身死才數月耳，天下四面而攻之，宗廟滅絕矣。", literal: "yet within only a few months after his death all under Heaven attacked from four sides and the ancestral temple was extinguished.", idiomatic: "yet within only a few months after his death all under Heaven attacked from four sides and the ancestral temple was extinguished." },
  { zh: "秦皇帝居滅絕之中而不自知者，何也？", literal: "The First Emperor of Qin dwelt in extinction yet did not know it—why?", idiomatic: "The First Emperor dwelt in extinction yet did not know it—why?" },
  { zh: "天下莫敢告也。", literal: "All under Heaven dared not tell him.", idiomatic: "All under Heaven dared not tell him." },
  { zh: "其所以莫敢告者，何也？", literal: "Why did none dare tell him?", idiomatic: "Why did none dare tell him?" },
  { zh: "亡養老之義，亡輔弼之臣，退誹謗之人，殺直諫之士。", literal: "He lacked the duty of nurturing the aged, lacked ministers who assisted and supported, dismissed those who criticized, and killed those who spoke bluntly.", idiomatic: "He lacked the duty of nurturing the aged, lacked assisting ministers, dismissed those who criticized, and killed those who spoke bluntly." },
  { zh: "是以道諛、媮合苟容，比其德則賢於堯、舜，課其功則賢於湯、武；", literal: "Thus the way of flattery and shameless compliance: compared in virtue he surpassed Yao and Shun; judged in achievement he surpassed Tang and Wu;", idiomatic: "Thus the way of flattery and shameless compliance: in comparing his virtue he surpassed Yao and Shun; in judging his achievement he surpassed Tang and Wu;" },
  { zh: "天下已潰而莫之告也。", literal: "all under Heaven had already collapsed yet none told him.", idiomatic: "all under Heaven had already collapsed yet none told him." },
  { zh: ":今陛下使天下舉賢良方正之士，天下皆欣欣焉曰：『將興堯舜之道、三王之功矣。", literal: ": Now Your Majesty has caused all under Heaven to recommend worthy and upright men; all under Heaven rejoice and say, ‘He is about to raise the Way of Yao and Shun and the achievement of the Three Kings.", idiomatic: ": Now Your Majesty has caused all under Heaven to recommend worthy and upright men; all under Heaven rejoice and say, ‘He is about to raise the way of Yao and Shun and the achievement of the Three Kings." },
  { zh: "』天下之士，莫不精白以承休德。", literal: "’ Scholars everywhere none fail to refine themselves to receive your gracious virtue.", idiomatic: "’ Scholars everywhere refine themselves to receive your gracious virtue." },
  { zh: "今方正之士皆在朝廷矣；", literal: "Now worthy and upright men are all at court;", idiomatic: "Now worthy and upright men are all at court;" },
  { zh: "又選其賢者，使為常侍、諸吏，與之馳驅射獵，一日再三出。", literal: "and choosing the worthiest among them, you make them attendants-in-ordinary and various officials and ride and hunt with them—going out three or four times in a day.", idiomatic: "yet choosing the worthiest among them, you make them attendants-in-ordinary and various officials and ride and hunt with them—going out three or four times in a day." },
  { zh: "臣恐朝廷之解馳，百官之墮於事也。", literal: "I fear the court will grow slack and hundreds of officials fall behind in their duties.", idiomatic: "I fear the court will grow slack and the hundred officials will neglect their duties." },
  { zh: "陛下即位，親自勉以厚天下，節用愛民，平獄緩刑；", literal: "Your Majesty since taking the throne has personally urged thickening all under Heaven, sparing expense and loving the people, leveling prisons and easing punishments;", idiomatic: "Since Your Majesty took the throne you have personally urged enriching all under Heaven, sparing expense and loving the people, leveling prisons and easing punishments;" },
  { zh: "天下莫不說喜。", literal: "and all under Heaven none fail to delight.", idiomatic: "and all under Heaven rejoices." },
  { zh: "臣聞山東吏布詔令，民雖老羸癃疾，扶杖而往聽之，願少須臾毋死，思見德化之成也。", literal: "I hear that when officers east of the mountains issued edicts, people though old, frail, and crippled leaned on staves to go listen, wishing to live a little longer without dying to see your transforming virtue fulfilled.", idiomatic: "I hear that when officers east of the mountains issued edicts, people though old, frail, and crippled leaned on staves to go and listen, wishing to live a little longer without dying to see your transforming virtue fulfilled." },
  { zh: "今功業方就，名聞方昭，四方鄉風而從；", literal: "Now your achievement is just being completed and your fame just spreading—the four quarters look to your wind and follow;", idiomatic: "Now your achievement is just being completed and your fame just spreading—the four quarters look to your example and follow;" },
  { zh: "豪俊之臣，方正之士，直與之日日獵射，擊兔、伐狐，以傷大業，絕天下之望，臣竊悼之。", literal: "yet worthy grandees and upright scholars go straight to daily hunting and shooting, striking rabbits and killing foxes, injuring the great work and cutting off all under Heaven's hopes—I mourn it privately.", idiomatic: "yet worthy grandees and upright scholars go straight to daily hunting and shooting, striking rabbits and killing foxes, injuring the great work and cutting off all under Heaven's hopes—I mourn it privately." },
  { zh: "古者大臣不得與宴游，使皆務其方而高其節，則群臣莫敢不正身修行，盡心以稱大體。", literal: "In antiquity great ministers did not join in feasting and outings; making all devote themselves to their duties and elevate their integrity, then no minister dared fail to straighten body and cultivate conduct and give full heart to match the great framework.", idiomatic: "In antiquity great ministers did not join in feasting and outings; if all were made to devote themselves to their duties and elevate their integrity, then no minister would dare fail to straighten his conduct and give full heart to match the great framework." },
  { zh: "夫士，修之於家而壞之於天子之廷，臣竊愍之。", literal: "Scholars refined at home yet ruined in the Son of Heaven's court—I pity it privately.", idiomatic: "Scholars refined at home yet ruined in the Son of Heaven's court—I pity it privately." },
  { zh: "陛下與眾臣宴游，與大臣、方正朝廷論議，游不失樂，朝不失禮，議不失計，軌事之大者也。", literal: "Your Majesty should feast and recreate with the multitude of ministers, but debate policy in court with great ministers and upright men—outing without losing pleasure, court without losing ritual, debate without losing plans: these are the great tracks of affairs.", idiomatic: "Your Majesty should feast and recreate with the multitude of ministers, but debate policy in court with great ministers and upright men—outing without losing pleasure, court without losing ritual, debate without losing plans: these are the great tracks of affairs." },
  { zh: "上嘉納其言。", literal: "The Emperor praised and adopted his words.", idiomatic: "The Emperor praised and adopted his words." },
  { zh: "上每朝，郎、從官上書疏，未嘗不止輦受其言。", literal: "At each audience the Emperor, when gentlemen and attendant officials submitted memorials, never failed to stop the palanquin and receive their words.", idiomatic: "At each audience, when gentlemen and attendant officials submitted memorials, the Emperor never failed to stop the palanquin and receive their words." },
  { zh: "言不可用置之，言可用采之，未嘗不稱善。", literal: "What could not be used he set aside; what could be used he adopted—he never failed to say it was good.", idiomatic: "What could not be used he set aside; what could be used he adopted—he never failed to praise it as good." },
  { zh: "帝從霸陵上欲西馳下峻阪。", literal: "The Emperor, coming from over Baling Ridge, wished to gallop westward down a steep slope.", idiomatic: "The Emperor, riding over Baling Ridge, wished to gallop westward down a steep slope." },
  { zh: "中郎將袁盎騎，並車攬轡。", literal: "Supervisor of the Gentlemen Yuan Ang rode alongside, drew abreast, and pulled the reins.", idiomatic: "Supervisor of the Gentlemen Yuan Ang rode alongside, drew abreast of the chariot, and pulled the reins." },
  { zh: "上曰：「將軍怯邪？", literal: "The Emperor said, “General, are you afraid?", idiomatic: "The Emperor said, “General, are you afraid?" },
  { zh: "」盎曰：「臣聞『千金之子，坐不垂堂』。", literal: "” Ang said, “I have heard, ‘A son worth a thousand in gold does not sit where the eaves overhang.’", idiomatic: "” Yuan Ang said, “I have heard, ‘A son worth a thousand in gold does not sit beneath overhanging eaves.’" },
  { zh: "聖主不乘危，不徼幸。", literal: "A sage lord does not ride in peril or court luck.", idiomatic: "A sage lord does not ride in peril or court luck." },
  { zh: "今陛下騁六飛馳下峻山，有如馬驚車敗，陛下縱自輕，奈高廟、太后何！", literal: "Now Your Majesty would gallop the six-horse team down a steep mountain—if the horses startle and the chariot breaks, though Your Majesty might make light of yourself, what of the High Ancestor's temple and the empress dowager!", idiomatic: "Now Your Majesty would gallop the six-horse team down a steep mountain—if the horses startle and the chariot breaks, though Your Majesty might make light of yourself, what of the High Ancestor's temple and the empress dowager!" },
  { zh: "」上乃止。", literal: "” The Emperor then stopped.", idiomatic: "” The Emperor then stopped." },
  { zh: "上所幸慎夫人，在禁中常與皇后同席坐。", literal: "Consort Shen, whom the Emperor favored, in the inner palace often sat on the same mat as the empress.", idiomatic: "Consort Shen, whom the Emperor favored, in the inner palace often sat on the same mat as the empress." },
  { zh: "及坐郎置，袁盎引卻慎夫人坐。", literal: "When they sat with attendants arranged, Yuan Ang drew back Consort Shen's seat.", idiomatic: "When they sat with attendants in place, Yuan Ang drew back Consort Shen's seat." },
  { zh: "慎夫人怒，不肯坐；", literal: "Consort Shen was angry and would not sit;", idiomatic: "Consort Shen was angry and would not sit;" },
  { zh: "上亦怒，起，入禁中。", literal: "the Emperor too was angry, rose, and went into the inner palace.", idiomatic: "the Emperor too was angry, rose, and went into the inner palace." },
  { zh: "盎因前說曰：「臣聞『尊卑有序，則上下和』。", literal: "Ang then advanced and said, “I have heard, ‘When high and low are ordered, then above and below are harmonized.’", idiomatic: "Yuan Ang then advanced and said, “I have heard, ‘When high and low are ordered, then above and below are harmonized.’" },
  { zh: "今陛下既已立-{后}-，慎夫人乃妾。", literal: "Now Your Majesty has already established -{后}-; Consort Shen is but a concubine.", idiomatic: "Now Your Majesty has already established -{后}-; Consort Shen is but a concubine." },
  { zh: "妾、主豈可與同坐哉！", literal: "How can concubine and mistress sit together!", idiomatic: "How can a concubine and the mistress sit together!" },
  { zh: "且陛下幸之，即厚賜之。", literal: "Moreover, if Your Majesty favors her, richly reward her—", idiomatic: "Moreover, if Your Majesty favors her, richly reward her—" },
  { zh: "陛下所以為慎夫人，適所以禍之也。", literal: "what Your Majesty does for Consort Shen is exactly what will bring calamity upon her.", idiomatic: "what Your Majesty does for Consort Shen is exactly what will bring calamity upon her." },
  { zh: "陛下獨不見『人彘』乎！", literal: "Has Your Majesty alone not seen the ‘human pig’!", idiomatic: "Has Your Majesty alone not seen the ‘human pig’!" },
  { zh: "」於是上乃說，召語慎夫人，慎夫人賜盎金五十斤。", literal: "” Thereupon the Emperor was persuaded, summoned and told Consort Shen, and Consort Shen bestowed fifty jin of gold on Ang.", idiomatic: "” Thereupon the Emperor was persuaded, summoned Consort Shen and spoke to her, and Consort Shen bestowed fifty jin of gold on Yuan Ang." },
  { zh: "賈誼說上曰：", literal: "Jia Yi spoke to the Emperor, saying:", idiomatic: "Jia Yi spoke to the Emperor, saying:" },
  { zh: ":「《管子》曰：『倉廩實而知禮節，衣食足而知榮辱。", literal: ": “The Guanzi says, ‘When granaries are full, then ritual and propriety are known; when clothing and food are sufficient, then honor and shame are known.", idiomatic: ": “The Guanzi says, ‘When granaries are full, then ritual and propriety are known; when clothing and food are sufficient, then honor and shame are known." },
  { zh: "』民不足而可治者，自古及今，未之嘗聞。", literal: "’ That the people are insufficient yet the state can be governed—from antiquity until now, none has ever heard of it.", idiomatic: "’ That the people are insufficient yet the state can be governed—from antiquity until now, none has ever heard of it." },
  { zh: "古之人曰：『一夫不耕，或受之饑；", literal: "The men of antiquity said: ‘If one man does not plow, someone may suffer hunger from it;", idiomatic: "The ancients said: ‘If one man does not plow, someone may go hungry;" },
  { zh: "一女不織，或受之寒。", literal: "if one woman does not weave, someone may suffer cold from it.", idiomatic: "if one woman does not weave, someone may go cold." },
  { zh: "』生之有時而用之亡度，則物力必屈。", literal: "’ Birth has its seasons yet use is without measure—then material power must be exhausted.", idiomatic: "’ Production has its seasons, yet consumption knows no limit—then material resources must fail." },
  { zh: "古之治天下，至纖至悉，故其畜積足恃。", literal: "In antiquity in governing all under Heaven it was most minute and most thorough; therefore their stored accumulations could be relied upon.", idiomatic: "In antiquity those who governed the realm were thorough to the finest detail, so their stored reserves could be trusted." },
  { zh: "今背本而趨末者甚眾，是天下之大殘也！", literal: "Now those who turn their backs on the root and rush to the tip are very many—this is the great mutilator of all under Heaven!", idiomatic: "Today many abandon the fundamental and rush to the secondary—this is the great destroyer of the realm!" },
  { zh: "淫侈之俗，日日以長，是天下之大賊也！", literal: "The custom of dissipation and extravagance grows day by day—this is the great thief of all under Heaven!", idiomatic: "The habit of excess and extravagance grows daily—this is the great thief of the realm!" },
  { zh: "殘、賊公行，莫之或止；", literal: "The mutilator and thief walk abroad openly, and none halt them;", idiomatic: "Destroyer and thief go unchecked, and no one stops them;" },
  { zh: "大命將泛，莫之振救。", literal: "the great mandate is about to be flooded away, and none rouses to save it.", idiomatic: "the nation's vital strength is about to fail, and no one stirs to rescue it." },
  { zh: "生之者甚少而靡之者甚多，天下財產何得不厥。", literal: "Those who produce are very few while those who waste are very many—how can the wealth and goods of all under Heaven not be exhausted?", idiomatic: "Producers are few and spenders many—how can the realm's wealth not be depleted?" },
  { zh: ":漢之為漢，幾四十年矣，公私之積，猶可哀痛。", literal: ": Han as Han has been almost forty years, yet public and private accumulations are still pitiable.", idiomatic: ": The Han dynasty has ruled for nearly forty years, yet public and private stores remain pitifully thin." },
  { zh: "失時不雨，民且狼顧；", literal: "If the seasons miss their rain, the people will look back like wolves;", idiomatic: "If the seasons fail and rains do not come, the people will look about in alarm;" },
  { zh: "歲惡不入，請賣爵子。", literal: "if the harvest is bad and dues do not come in, they beg to sell rank and children.", idiomatic: "if the harvest fails and taxes cannot be paid, they beg to sell their noble ranks and even their children." },
  { zh: "既聞耳矣，安有為天下阽危者若是而上不驚者！", literal: "This has already reached Our ears—how can there be one who brings all under Heaven to the brink such as this while those above are not alarmed!", idiomatic: "This has already reached my ears—how can the realm be brought to such peril while those above are not alarmed!" },
  { zh: ":世之有饑、穰，天之行也；", literal: ": Famine and abundance in the world are Heaven's course;", idiomatic: ": Famine and plenty in the world are Heaven's way;" },
  { zh: "禹、湯被之矣。", literal: "Yu and Tang suffered them.", idiomatic: "Yu and Tang endured them." },
  { zh: "即不幸有方二三千里之旱，國胡以相恤？", literal: "If by misfortune there is drought over a region of two or three thousand li, with what will the state aid one another?", idiomatic: "If misfortune brings drought across two or three thousand li, how will the state aid one another?" },
  { zh: "卒然邊境有急，數十百萬之眾，國胡以饋之？", literal: "If suddenly the border has an emergency and hosts of hundreds of thousands and millions— with what will the state feed them?", idiomatic: "If suddenly the border is threatened and armies of hundreds of thousands or millions must be fed, with what will the state supply them?" },
  { zh: "兵、旱相乘，天下大屈，有勇力者聚徒而衡擊，罷夫、羸老，易子上咬其骨。", literal: "When war and drought multiply each other, all under Heaven is greatly depleted; men of courage and strength gather gangs and strike horizontally, exhausted husbands and frail old men exchange sons and gnaw their bones.", idiomatic: "When war and drought strike together, the realm is drained; the strong gather bands and rampage, while the worn-out and the aged exchange sons and gnaw on bones." },
  { zh: "政治未畢通也，遠方之能僭擬者並舉而爭起矣；", literal: "Government is not yet fully communicated, and those in distant places who can usurp and imitate will together rise competing;", idiomatic: "Before government is fully restored, distant men who would usurp the throne will rise together in rivalry;" },
  { zh: "乃駭而圖之，豈將有及乎！", literal: "only then in alarm will one scheme—is there still time to reach it?", idiomatic: "only then in alarm will you take counsel—will it still be in time!" },
  { zh: "夫積貯者，天下之大命也。", literal: "Accumulated stores are the great mandate of all under Heaven.", idiomatic: "Stored grain is the lifeblood of the realm." },
  { zh: "苟粟多而財有餘，何為而不成！", literal: "If grain is abundant and wealth has surplus, what doing would not succeed!", idiomatic: "If grain is plentiful and resources ample, what undertaking would not succeed!" },
  { zh: "以攻則取，以守則固，以戰則勝，懷敵附遠，何招而不至！", literal: "In attack one takes, in defense one is firm, in battle one wins; cherishing enemies and drawing distant ones near—what summons would not arrive!", idiomatic: "In attack you prevail, in defense you stand firm, in battle you win; win over foes and draw the distant near—what invitation would they not answer!" },
  { zh: ":今驅民而歸之農，皆著於本。", literal: ": Now drive the people back to agriculture and all attach to the root.", idiomatic: ": Now drive the people back to farming and fix them all on the fundamental." },
  { zh: "使天下各食其力，末技、游食之民轉而緣南晦則畜積足而人樂其所矣。", literal: "Make all under Heaven each eat by his labor; those of trivial skills and wandering eaters turn instead to attach to south hui—then stored accumulation is sufficient and men rejoice in their stations.", idiomatic: "Let all under Heaven live by their own labor; let those in petty crafts and idle wandering turn to the south-facing fields—then stores will be full and the people content in their places." },
  { zh: "可以為富安天下，而直為此廩廩也，竊為陛下惜之！", literal: "One could thereby enrich and settle all under Heaven, yet Your Majesty simply lets granaries run this meager—I privately grieve for Your Majesty!", idiomatic: "By this you could enrich and secure the realm, yet Your Majesty lets the granaries run so thin—I grieve for you in private!" },
  { zh: "上感誼言，春，正月，丁亥，詔開藉田，上親耕以率天下之民。", literal: "The Emperor was moved by Yi's words; in spring, the first month, on dinghai, an edict opened the sacred field; the Emperor personally plowed to lead the people of all under Heaven.", idiomatic: "The Emperor was moved by Jia Yi's words; in spring, the first month, on dinghai, an edict opened the sacred plowing field and the Emperor farmed in person to lead the people of the realm." },
  { zh: "----5三月，有司請立皇子為諸侯王。", literal: "----5 In the third month the responsible officials asked to establish the imperial sons as feudal kings.", idiomatic: "----5 In the third month officials asked that the imperial sons be enfeoffed as feudal kings." },
  { zh: "詔先立趙幽王少子辟強為河間王，朱虛侯章為城陽王，東牟侯興居為濟北王；", literal: "An edict first established the young son of King You of Zhao, Piqiang, as King of Hejian; the Marquis of Zhu Xu, Zhang, as King of Chengyang; the Marquis of Dongmou, Xingju, as King of Jibei;", idiomatic: "An edict first made the young son of King You of Zhao, Piqiang, King of Hejian; the Marquis of Zhu Xu, Zhang, King of Chengyang; and the Marquis of Dongmou, Xingju, King of Jibei;" },
  { zh: "然後立皇子武為代王，參為太原王，揖為梁王。", literal: "then established the imperial son Wu as King of Dai, Can as King of Taiyuan, and Yi as King of Liang.", idiomatic: "then made the imperial sons Wu King of Dai, Can King of Taiyuan, and Yi King of Liang." },
  { zh: "----6五月，詔曰：「古之治天下，朝有進善之旌，誹謗之木，所以通治道而來諫者也。", literal: "----6 In the fifth month an edict said: “In antiquity in governing all under Heaven, at court there were banners for advancing goodness and posts for slander—by these the way of governance was communicated and remonstrance brought in.", idiomatic: "----6 In the fifth month an edict said: “In antiquity those who governed the realm set up banners to reward good counsel and posts for criticism, so that the way of rule was kept open and remonstrance could reach the throne." },
  { zh: "今法有誹謗、妖言之罪，是使眾臣不敢盡情而上無由聞過失也，將何以來遠方之賢良！", literal: "Now the law has crimes of slander and demon talk—this makes the multitude of ministers not dare speak fully while those above have no means to hear faults; with what will worthy and good men from afar be brought in!", idiomatic: "Now the law punishes slander and ‘demon talk,’ so ministers dare not speak plainly and those above have no way to hear their faults—how will worthy men from afar be drawn in!" },
  { zh: "其除之！", literal: "Let them be abolished!", idiomatic: "Abolish them!" },
  { zh: "」----7九月，詔曰：「農，天下之大本也，民所恃以生也；", literal: "” ----7 In the ninth month an edict said: “Agriculture is the great root of all under Heaven, what the people rely on to live;", idiomatic: "” ----7 In the ninth month an edict said: “Agriculture is the great foundation of the realm; the people depend on it for their livelihood;" },
  { zh: "而民或不務本而事末，故生不遂。", literal: "yet the people sometimes do not attend to the root but serve the tip, therefore life does not succeed.", idiomatic: "yet some neglect the root and pursue the secondary, so their livelihood fails." },
  { zh: "朕憂其然，故今茲親率群臣農以勸之；", literal: "We worry at this; therefore now We personally lead the great ministers in farming to encourage it;", idiomatic: "I am troubled by this, and therefore now personally lead the ministers in farming to encourage it;" },
  { zh: "其賜天下民今年田租之半。", literal: "let half this year's field tax for the people of all under Heaven be bestowed.", idiomatic: "grant the people of the realm half this year's land tax." },
  { zh: "」----8燕敬王澤薨。", literal: "” ----8 King Jing of Yan, Ze, died.", idiomatic: "” ----8 King Jing of Yan, Liu Ze, died." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
